{
  "name": "BrainBoost AI Quiz",
  "description": "An intelligent, Gemini-powered quiz application that generates custom learning challenges on any topic instantly."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Question {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export type Difficulty = 'easy' | 'medium' | 'hard';

export interface QuizSetup {
  topic: string;
  count: number;
  difficulty: Difficulty;
}

export enum AppState {
  SETUP,
  LOADING,
  PLAYING,
  RESULTS
}

export interface UserAnswer {
  questionIndex: number;
  selectedIndex: number;
  isCorrect: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Question, QuizSetup } from "../types";

export const generateQuiz = async (setup: QuizSetup): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Generate a quiz about "${setup.topic}". 
  The difficulty level is ${setup.difficulty}. 
  Provide exactly ${setup.count} high-quality multiple-choice questions. 
  Each question must have exactly 4 options. 
  Include a short explanation for why the correct answer is right.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Array of exactly 4 strings representing answer choices."
            },
            correctIndex: { 
              type: Type.INTEGER,
              description: "The 0-based index of the correct option."
            },
            explanation: { type: Type.STRING }
          },
          required: ["question", "options", "correctIndex", "explanation"],
        },
      },
    },
  });

  try {
    const text = response.text || '[]';
    const questions: Question[] = JSON.parse(text);
    return questions;
  } catch (error) {
    console.error("Failed to parse quiz JSON:", error);
    throw new Error("Could not generate valid quiz data. Please try again.");
  }
};

import React, { useState, useCallback } from 'react';
import { AppState, Question, QuizSetup, UserAnswer, Difficulty } from './types';
import { generateQuiz } from './services/geminiService';
import SetupView from './components/SetupView';
import QuizEngine from './components/QuizEngine';
import ResultsView from './components/ResultsView';
import LoadingView from './components/LoadingView';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.SETUP);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [error, setError] = useState<string | null>(null);

  const startQuiz = async (setup: QuizSetup) => {
    setState(AppState.LOADING);
    setError(null);
    try {
      const generatedQuestions = await generateQuiz(setup);
      if (generatedQuestions.length === 0) {
        throw new Error("No questions generated.");
      }
      setQuestions(generatedQuestions);
      setUserAnswers([]);
      setState(AppState.PLAYING);
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred");
      setState(AppState.SETUP);
    }
  };

  const handleComplete = (answers: UserAnswer[]) => {
    setUserAnswers(answers);
    setState(AppState.RESULTS);
  };

  const reset = () => {
    setState(AppState.SETUP);
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderContent = () => {
    switch (state) {
      case AppState.SETUP:
        return <SetupView onStart={startQuiz} error={error} />;
      case AppState.LOADING:
        return <LoadingView />;
      case AppState.PLAYING:
        return (
          <QuizEngine 
            questions={questions} 
            onComplete={handleComplete} 
            onQuit={reset}
          />
        );
      case AppState.RESULTS:
        return (
          <ResultsView 
            questions={questions} 
            answers={userAnswers} 
            onRestart={reset} 
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-2xl">
        <header className="text-center mb-8">
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight mb-2">
            BrainBoost <span className="text-indigo-600">AI</span>
          </h1>
          <p className="text-slate-500 font-medium">Smart learning powered by Gemini</p>
        </header>

        <main className="animate-slide-in">
          {renderContent()}
        </main>
      </div>

      <footer className="mt-12 text-slate-400 text-sm">
        &copy; {new Date().getFullYear()} BrainBoost AI. All rights reserved.
      </footer>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { QuizSetup, Difficulty } from '../types';

interface SetupViewProps {
  onStart: (setup: QuizSetup) => void;
  error: string | null;
}

const SetupView: React.FC<SetupViewProps> = ({ onStart, error }) => {
  const [topic, setTopic] = useState('');
  const [count, setCount] = useState(5);
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;
    onStart({ topic, count, difficulty });
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50">
      <h2 className="text-2xl font-bold text-slate-800 mb-6">Create Your Challenge</h2>

      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label className="block text-sm font-semibold text-slate-700 mb-2">What do you want to learn about?</label>
          <input
            type="text"
            placeholder="e.g. Ancient Rome, React Hooks, Baking..."
            className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 transition-all outline-none text-slate-800"
            value={topic}
            onChange={(e) => setTopic(e.target.value)}
            required
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Number of Questions</label>
            <select
              className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none"
              value={count}
              onChange={(e) => setCount(Number(e.target.value))}
            >
              {[3, 5, 10, 15].map(n => (
                <option key={n} value={n}>{n} Questions</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Difficulty</label>
            <select
              className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none"
              value={difficulty}
              onChange={(e) => setDifficulty(e.target.value as Difficulty)}
            >
              <option value="easy">Easy</option>
              <option value="medium">Medium</option>
              <option value="hard">Hard</option>
            </select>
          </div>
        </div>

        <button
          type="submit"
          disabled={!topic.trim()}
          className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-indigo-200 mt-4 active:scale-95"
        >
          Generate Quiz
        </button>
      </form>
    </div>
  );
};

export default SetupView;

import React, { useState, useEffect } from 'react';
import { Question, UserAnswer } from '../types';

interface QuizEngineProps {
  questions: Question[];
  onComplete: (answers: UserAnswer[]) => void;
  onQuit: () => void;
}

const QuizEngine: React.FC<QuizEngineProps> = ({ questions, onComplete, onQuit }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState<UserAnswer[]>([]);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);

  const currentQuestion = questions[currentIdx];

  const handleOptionSelect = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
  };

  const handleConfirm = () => {
    if (selectedOption === null) return;

    const isCorrect = selectedOption === currentQuestion.correctIndex;
    const newAnswer: UserAnswer = {
      questionIndex: currentIdx,
      selectedIndex: selectedOption,
      isCorrect
    };

    setAnswers(prev => [...prev, newAnswer]);
    setIsAnswered(true);
  };

  const handleNext = () => {
    if (currentIdx < questions.length - 1) {
      setCurrentIdx(currentIdx + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      onComplete([...answers]);
    }
  };

  const progress = ((currentIdx + (isAnswered ? 1 : 0)) / questions.length) * 100;

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100 w-full">
      <div className="flex justify-between items-center mb-6">
        <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">
          Question {currentIdx + 1} of {questions.length}
        </span>
        <button 
          onClick={onQuit}
          className="text-sm font-semibold text-slate-400 hover:text-red-500 transition-colors"
        >
          Quit
        </button>
      </div>

      <div className="w-full bg-slate-100 h-2 rounded-full mb-8 overflow-hidden">
        <div 
          className="h-full bg-indigo-600 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      <h3 className="text-2xl font-bold text-slate-800 mb-8 leading-tight">
        {currentQuestion.question}
      </h3>

      <div className="space-y-4 mb-10">
        {currentQuestion.options.map((option, idx) => {
          let style = "bg-slate-50 border-2 border-slate-100 text-slate-700 hover:border-indigo-200";
          if (selectedOption === idx) {
            style = "bg-indigo-50 border-2 border-indigo-500 text-indigo-700";
          }
          if (isAnswered) {
            if (idx === currentQuestion.correctIndex) {
              style = "bg-green-50 border-2 border-green-500 text-green-700";
            } else if (selectedOption === idx) {
              style = "bg-red-50 border-2 border-red-500 text-red-700";
            } else {
              style = "bg-slate-50 border-2 border-slate-100 text-slate-400 opacity-60";
            }
          }

          return (
            <button
              key={idx}
              onClick={() => handleOptionSelect(idx)}
              disabled={isAnswered}
              className={`w-full p-5 rounded-2xl text-left font-semibold transition-all duration-200 transform ${style} ${!isAnswered && 'active:scale-[0.98]'}`}
            >
              <div className="flex items-center">
                <span className="w-8 h-8 rounded-full bg-white/50 flex items-center justify-center mr-4 text-sm">
                  {String.fromCharCode(65 + idx)}
                </span>
                {option}
              </div>
            </button>
          );
        })}
      </div>

      {isAnswered && (
        <div className="mb-8 p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-slide-in">
          <p className="text-sm text-slate-600 leading-relaxed italic">
            <span className="font-bold text-slate-800 not-italic mr-1">Explanation:</span>
            {currentQuestion.explanation}
          </p>
        </div>
      )}

      <div className="flex justify-end">
        {!isAnswered ? (
          <button
            onClick={handleConfirm}
            disabled={selectedOption === null}
            className="px-10 py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white font-bold rounded-2xl shadow-lg transition-all active:scale-95"
          >
            Check Answer
          </button>
        ) : (
          <button
            onClick={handleNext}
            className="px-10 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg transition-all active:scale-95"
          >
            {currentIdx === questions.length - 1 ? 'Finish' : 'Next Question'}
          </button>
        )}
      </div>
    </div>
  );
};

export default QuizEngine;

import React from 'react';
import { Question, UserAnswer } from '../types';

interface ResultsViewProps {
  questions: Question[];
  answers: UserAnswer[];
  onRestart: () => void;
}

const ResultsView: React.FC<ResultsViewProps> = ({ questions, answers, onRestart }) => {
  const score = answers.filter(a => a.isCorrect).length;
  const percentage = Math.round((score / questions.length) * 100);

  let message = "Keep learning!";
  let icon = "🌱";
  if (percentage === 100) { message = "Perfect Score!"; icon = "🏆"; }
  else if (percentage >= 80) { message = "Excellent Job!"; icon = "🌟"; }
  else if (percentage >= 50) { message = "Good Effort!"; icon = "👍"; }

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 overflow-hidden border border-indigo-50">
      <div className="bg-indigo-600 p-10 text-center text-white">
        <div className="text-6xl mb-4">{icon}</div>
        <h2 className="text-3xl font-bold mb-1">{message}</h2>
        <p className="opacity-90 font-medium">You scored {score} out of {questions.length}</p>

        <div className="mt-8 relative inline-flex items-center justify-center">
            <svg className="w-24 h-24 transform -rotate-90">
                <circle
                    className="text-indigo-800"
                    strokeWidth="8"
                    stroke="currentColor"
                    fill="transparent"
                    r="40"
                    cx="48"
                    cy="48"
                />
                <circle
                    className="text-white transition-all duration-1000 ease-out"
                    strokeWidth="8"
                    strokeDasharray={251.2}
                    strokeDashoffset={251.2 - (251.2 * percentage) / 100}
                    strokeLinecap="round"
                    stroke="currentColor"
                    fill="transparent"
                    r="40"
                    cx="48"
                    cy="48"
                />
            </svg>
            <span className="absolute text-xl font-bold">{percentage}%</span>
        </div>
      </div>

      <div className="p-8 max-h-[400px] overflow-y-auto bg-slate-50">
        <h3 className="text-lg font-bold text-slate-800 mb-6">Review Answers</h3>
        <div className="space-y-4">
          {questions.map((q, idx) => {
            const userAnswer = answers.find(a => a.questionIndex === idx);
            return (
              <div key={idx} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                <div className="flex items-start mb-3">
                    <span className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center mr-3 mt-0.5 ${userAnswer?.isCorrect ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                        {userAnswer?.isCorrect ? '✓' : '✕'}
                    </span>
                    <p className="font-semibold text-slate-800">{q.question}</p>
                </div>
                {!userAnswer?.isCorrect && (
                    <p className="text-sm text-slate-500 ml-9">
                        Correct answer: <span className="font-bold text-green-600">{q.options[q.correctIndex]}</span>
                    </p>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div className="p-8 bg-white border-t border-slate-100">
        <button
          onClick={onRestart}
          className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 transition-all active:scale-95"
        >
          Take Another Quiz
        </button>
      </div>
    </div>
  );
};

export default ResultsView;

import React, { useEffect, useState } from 'react';

const LoadingView: React.FC = () => {
  const [messageIdx, setMessageIdx] = useState(0);
  const messages = [
    "Consulting the knowledge base...",
    "Brainstorming creative questions...",
    "Setting up the challenge...",
    "Almost ready to start!",
    "Gemini is thinking deeply..."
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setMessageIdx(prev => (prev + 1) % messages.length);
    }, 2000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-12 flex flex-col items-center justify-center text-center border border-indigo-50 min-h-[400px]">
      <div className="relative w-20 h-20 mb-8">
        <div className="absolute inset-0 border-4 border-indigo-100 rounded-full"></div>
        <div className="absolute inset-0 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin"></div>
      </div>
      <h2 className="text-xl font-bold text-slate-800 mb-2 animate-pulse">
        {messages[messageIdx]}
      </h2>
      <p className="text-slate-400 text-sm">Generating your custom AI quiz...</p>
    </div>
  );
};

export default LoadingView;

