import { GoogleGenAI, Type } from "@google/genai";
import { Question, QuizSetup } from "../types";

export const generateQuiz = async (setup: QuizSetup): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const prompt = `Hãy tạo một bộ câu hỏi trắc nghiệm về chủ đề "${setup.topic}". 
  Tất cả nội dung (câu hỏi, các lựa chọn, giải thích) PHẢI bằng tiếng Việt.
  Mức độ khó là ${setup.difficulty === 'easy' ? 'dễ' : setup.difficulty === 'medium' ? 'trung bình' : 'khó'}. 
  Cung cấp đúng ${setup.count} câu hỏi trắc nghiệm chất lượng cao. 
  Mỗi câu hỏi phải có đúng 4 lựa chọn. 
  Bao gồm một lời giải thích ngắn gọn tại sao đáp án đó lại đúng.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Mảng chứa đúng 4 chuỗi đại diện cho các lựa chọn trả lời."
            },
            correctIndex: { 
              type: Type.INTEGER,
              description: "Chỉ số (0-based) của đáp án đúng."
            },
            explanation: { type: Type.STRING }
          },
          required: ["question", "options", "correctIndex", "explanation"],
        },
      },
    },
  });

  try {
    const text = response.text || '[]';
    const questions: Question[] = JSON.parse(text);
    return questions;
  } catch (error) {
    console.error("Lỗi khi phân tích JSON câu hỏi:", error);
    throw new Error("Không thể tạo dữ liệu trắc nghiệm hợp lệ. Vui lòng thử lại.");
  }
};

import React, { useState, useCallback } from 'react';
import { AppState, Question, QuizSetup, UserAnswer, Difficulty } from './types';
import { generateQuiz } from './services/geminiService';
import SetupView from './components/SetupView';
import QuizEngine from './components/QuizEngine';
import ResultsView from './components/ResultsView';
import LoadingView from './components/LoadingView';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.SETUP);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [error, setError] = useState<string | null>(null);

  const startQuiz = async (setup: QuizSetup) => {
    setState(AppState.LOADING);
    setError(null);
    try {
      const generatedQuestions = await generateQuiz(setup);
      if (generatedQuestions.length === 0) {
        throw new Error("Không có câu hỏi nào được tạo ra.");
      }
      setQuestions(generatedQuestions);
      setUserAnswers([]);
      setState(AppState.PLAYING);
    } catch (err: any) {
      setError(err.message || "Đã xảy ra lỗi không mong muốn");
      setState(AppState.SETUP);
    }
  };

  const handleComplete = (answers: UserAnswer[]) => {
    setUserAnswers(answers);
    setState(AppState.RESULTS);
  };

  const reset = () => {
    setState(AppState.SETUP);
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderContent = () => {
    switch (state) {
      case AppState.SETUP:
        return <SetupView onStart={startQuiz} error={error} />;
      case AppState.LOADING:
        return <LoadingView />;
      case AppState.PLAYING:
        return (
          <QuizEngine 
            questions={questions} 
            onComplete={handleComplete} 
            onQuit={reset}
          />
        );
      case AppState.RESULTS:
        return (
          <ResultsView 
            questions={questions} 
            answers={userAnswers} 
            onRestart={reset} 
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-2xl">
        <header className="text-center mb-8">
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight mb-2">
            BrainBoost <span className="text-indigo-600">AI</span>
          </h1>
          <p className="text-slate-500 font-medium">Học tập thông minh cùng Gemini</p>
        </header>

