import React, { useState, useEffect } from 'react';
import { Question, UserAnswer } from '../types';

interface QuizEngineProps {
  questions: Question[];
  onComplete: (answers: UserAnswer[]) => void;
  onQuit: () => void;
}

const QuizEngine: React.FC<QuizEngineProps> = ({ questions, onComplete, onQuit }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState<UserAnswer[]>([]);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);

  const currentQuestion = questions[currentIdx];

  const handleOptionSelect = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
  };

  const handleConfirm = () => {
    if (selectedOption === null) return;

    const isCorrect = selectedOption === currentQuestion.correctIndex;
    const newAnswer: UserAnswer = {
      questionIndex: currentIdx,
      selectedIndex: selectedOption,
      isCorrect
    };

    setAnswers(prev => [...prev, newAnswer]);
    setIsAnswered(true);
  };

  const handleNext = () => {
    if (currentIdx < questions.length - 1) {
      setCurrentIdx(currentIdx + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      onComplete([...answers]);
    }
  };

  const progress = ((currentIdx + (isAnswered ? 1 : 0)) / questions.length) * 100;

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100 w-full">
      <div className="flex justify-between items-center mb-6">
        <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">
          Câu hỏi {currentIdx + 1} trên {questions.length}
        </span>
        <button 
          onClick={onQuit}
          className="text-sm font-semibold text-slate-400 hover:text-red-500 transition-colors"
        >
          Thoát
        </button>
      </div>

      <div className="w-full bg-slate-100 h-2 rounded-full mb-8 overflow-hidden">
        <div 
          className="h-full bg-indigo-600 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      <h3 className="text-2xl font-bold text-slate-800 mb-8 leading-tight">
        {currentQuestion.question}
      </h3>

      <div className="space-y-4 mb-10">
        {currentQuestion.options.map((option, idx) => {
          let style = "bg-slate-50 border-2 border-slate-100 text-slate-700 hover:border-indigo-200";
          if (selectedOption === idx) {
            style = "bg-indigo-50 border-2 border-indigo-500 text-indigo-700";
          }
          if (isAnswered) {
            if (idx === currentQuestion.correctIndex) {
              style = "bg-green-50 border-2 border-green-500 text-green-700";
            } else if (selectedOption === idx) {
              style = "bg-red-50 border-2 border-red-500 text-red-700";
            } else {
              style = "bg-slate-50 border-2 border-slate-100 text-slate-400 opacity-60";
            }
          }

          return (
            <button
              key={idx}
              onClick={() => handleOptionSelect(idx)}
              disabled={isAnswered}
              className={`w-full p-5 rounded-2xl text-left font-semibold transition-all duration-200 transform ${style} ${!isAnswered && 'active:scale-[0.98]'}`}
            >
              <div className="flex items-center">
                <span className="w-8 h-8 rounded-full bg-white/50 flex items-center justify-center mr-4 text-sm">
                  {String.fromCharCode(65 + idx)}
                </span>
                {option}
              </div>
            </button>
          );
        })}
      </div>

      {isAnswered && (
        <div className="mb-8 p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-slide-in">
          <p className="text-sm text-slate-600 leading-relaxed italic">
            <span className="font-bold text-slate-800 not-italic mr-1">Giải thích:</span>
            {currentQuestion.explanation}
          </p>
        </div>
      )}

      <div className="flex justify-end">
        {!isAnswered ? (
          <button
            onClick={handleConfirm}
            disabled={selectedOption === null}
            className="px-10 py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white font-bold rounded-2xl shadow-lg transition-all active:scale-95"
          >
            Kiểm tra đáp án
          </button>
        ) : (
          <button
            onClick={handleNext}
            className="px-10 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg transition-all active:scale-95"
          >
            {currentIdx === questions.length - 1 ? 'Hoàn thành' : 'Câu tiếp theo'}
          </button>
        )}
      </div>
    </div>
  );
};

export default QuizEngine;

