            else if (idx === 1) rankIcon = '🥈';
            else if (idx === 2) rankIcon = '🥉';

            return (
              <tr key={entry.id} className="hover:bg-indigo-50/30 transition-colors">
                <td className="px-4 py-3 font-bold text-slate-400 w-16">
                    {rankIcon || idx + 1}
                </td>
                <td className="px-4 py-3">
                  <div className="font-semibold text-slate-800">{entry.playerName}</div>
                  <div className="text-xs text-slate-400 truncate max-w-[150px]">{entry.topic}</div>
                </td>
                <td className="px-4 py-3 text-right">
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-indigo-100 text-indigo-800">
                    {entry.score}/{entry.total}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

