interface SetupViewProps {
  onStart: (setup: QuizSetup) => void;
  error: string | null;
  leaderboard: LeaderboardEntry[];
}

const PREDEFINED_TOPICS = [
  { label: 'Lịch sử Việt Nam', icon: '🇻🇳' },
  { label: 'Địa lý thế giới', icon: '🌍' },
  { label: 'Khoa học & Vũ trụ', icon: '🚀' },
  { label: 'Lập trình React', icon: '💻' },
  { label: 'Tiếng Anh giao tiếp', icon: '🇬🇧' },
  { label: 'Văn học Việt Nam', icon: '✍️' },
  { label: 'Toán học vui', icon: '🔢' },
  { label: 'Kỹ năng sống', icon: '💡' },
];

const GRADE_STRUCTURE: Record<GradeLevel, string[]> = {
  primary: ['1', '2', '3', '4', '5'],
  secondary: ['6', '7', '8', '9'],
  highschool: ['10', '11', '12'],
  advanced: ['Đại học', 'Sau đại học', 'Đi làm'],
};

const SetupView: React.FC<SetupViewProps> = ({ onStart, error, leaderboard }) => {
  const [playerName, setPlayerName] = useState('');
  const [topic, setTopic] = useState('');
  const [count, setCount] = useState(10);
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');
  const [gradeLevel, setGradeLevel] = useState<GradeLevel>('primary');
  const [gradeClass, setGradeClass] = useState('1');
  const [bookSeries, setBookSeries] = useState<BookSeries>('none');
  const [advancedInstructions, setAdvancedInstructions] = useState('');
