  // Update class selection when level changes
  useEffect(() => {
    setGradeClass(GRADE_STRUCTURE[gradeLevel][0]);
  }, [gradeLevel]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim() || !playerName.trim()) return;
    onStart({ 
      playerName, 
      topic, 
      count, 
      difficulty, 
      gradeLevel, 
      gradeClass, 
      bookSeries,
      advancedInstructions 
    });
  };

  const selectTopic = (selectedTopic: string) => {
    setTopic(selectedTopic);
  };

  return (
    <div className="space-y-8">
      <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50">
        <h2 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            <span className="mr-3 text-indigo-600">✍️</span>
            Thiết lập trò chơi
        </h2>

        {error && (
