            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Tên của bạn</label>
              <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">👤</span>
                  <input
                      type="text"
                      placeholder="Nhập tên..."
                      className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 transition-all outline-none text-slate-800"
                      value={playerName}
