              <select
                className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                value={gradeLevel}
                onChange={(e) => setGradeLevel(e.target.value as GradeLevel)}
              >
                <option value="primary">Tiểu học</option>
                <option value="secondary">THCS</option>
                <option value="highschool">THPT</option>
