                        value={advancedInstructions}
                        onChange={(e) => setAdvancedInstructions(e.target.value)}
                    />
                </div>
            )}
          </div>

          <button
            type="submit"
            disabled={!topic.trim() || !playerName.trim()}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-bold py-4 rounded-2xl transition-all shadow-lg shadow-indigo-200 mt-4 active:scale-95"
          >
            Bắt đầu bài trắc nghiệm
          </button>
        </form>
      </div>

      {leaderboard.length > 0 && (
          <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100">
              <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center">
                <span className="mr-3 text-yellow-500">🏆</span>
                Bảng xếp hạng
              </h2>
              <Leaderboard entries={leaderboard} />
          </div>
      )}
    </div>
  );
};

export default SetupView;

export interface Question {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export type Difficulty = 'easy' | 'medium' | 'hard';
export type GradeLevel = 'primary' | 'secondary' | 'highschool' | 'advanced';
export type BookSeries = 'canh_dieu' | 'ket_noi_tri_thuc' | 'chan_troi_sang_tao' | 'none';
export type ContentType = 'topic' | 'lesson';

export interface QuizSetup {
  playerName: string;
  topic: string;
  contentType: ContentType;
  count: number;
  difficulty: Difficulty;
  gradeLevel: GradeLevel;
  gradeClass: string;
  bookSeries: BookSeries;
  advancedInstructions?: string;
}

export enum AppState {
  SETUP,
  LOADING,
  PLAYING,
  RESULTS
}

export interface UserAnswer {
  questionIndex: number;
  selectedIndex: number;
  isCorrect: boolean;
}

export interface LeaderboardEntry {
  id: string;
  playerName: string;
  score: number;
  total: number;
  topic: string;
  date: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Question, QuizSetup } from "../types";

export const generateQuiz = async (setup: QuizSetup): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const gradeNames: Record<string, string> = {
    primary: 'Tiểu học',
    secondary: 'Trung học cơ sở',
    highschool: 'Trung học phổ thông',
    advanced: 'Đại học / Người đi làm'
  };

  const bookSeriesNames: Record<string, string> = {
    canh_dieu: 'Cánh diều',
    ket_noi_tri_thuc: 'Kết nối tri thức với cuộc sống',
    chan_troi_sang_tao: 'Chân trời sáng tạo',
    none: 'Chương trình chuẩn'
  };

  const typeDesc = setup.contentType === 'topic' ? 'theo chủ đề rộng' : 'theo một bài học cụ thể';

  let prompt = `Hãy tạo một bộ câu hỏi trắc nghiệm ${typeDesc} về: "${setup.topic}". 
  Tất cả nội dung (câu hỏi, các lựa chọn, giải thích) PHẢI bằng tiếng Việt.

  ĐỐI TƯỢNG: Trình độ ${gradeNames[setup.gradeLevel]}, Lớp ${setup.gradeClass}.
  BỘ SÁCH GIÁO KHOA: ${bookSeriesNames[setup.bookSeries]}.
  Mức độ khó là ${setup.difficulty === 'easy' ? 'dễ' : setup.difficulty === 'medium' ? 'trung bình' : 'khó'}. 

  Cung cấp đúng CHÍNH XÁC ${setup.count} câu hỏi trắc nghiệm chất lượng cao. 
  Đảm bảo nội dung bám sát chương trình học và tính chất của ${setup.contentType === 'topic' ? 'một chủ đề tổng quát' : 'một bài học chi tiết'}.
  Mỗi câu hỏi phải có đúng 4 lựa chọn. 
  Bao gồm một lời giải thích ngắn gọn, súc tích và chính xác.`;

  if (setup.advancedInstructions && setup.advancedInstructions.trim() !== "") {
    prompt += `\n\nLƯU Ý NÂNG CAO TỪ NGƯỜI DÙNG: "${setup.advancedInstructions}". 
    Hãy điều chỉnh nội dung câu hỏi để tuân thủ nghiêm ngặt các yêu cầu bổ sung này.`;
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Mảng chứa đúng 4 chuỗi đại diện cho các lựa chọn trả lời."
            },
            correctIndex: { 
              type: Type.INTEGER,
              description: "Chỉ số (0-based) của đáp án đúng."
            },
            explanation: { type: Type.STRING }
          },
          required: ["question", "options", "correctIndex", "explanation"],
        },
      },
    },
  });

  try {
    const text = response.text || '[]';
    const questions: Question[] = JSON.parse(text);
    return questions;
  } catch (error) {
    console.error("Lỗi khi phân tích JSON câu hỏi:", error);
    throw new Error("Không thể tạo dữ liệu trắc nghiệm. Vui lòng thử lại với số lượng câu hỏi ít hơn hoặc chủ đề rõ ràng hơn.");
  }
};

import React, { useState, useEffect } from 'react';
import { QuizSetup, Difficulty, LeaderboardEntry, GradeLevel, BookSeries, ContentType } from '../types';
import Leaderboard from './Leaderboard';

interface SetupViewProps {
  onStart: (setup: QuizSetup) => void;
  error: string | null;
  leaderboard: LeaderboardEntry[];
}

const PREDEFINED_TOPICS = [
  { label: 'Lịch sử Việt Nam', icon: '🇻🇳' },
  { label: 'Địa lý thế giới', icon: '🌍' },
  { label: 'Khoa học & Vũ trụ', icon: '🚀' },
  { label: 'Lập trình React', icon: '💻' },
  { label: 'Tiếng Anh giao tiếp', icon: '🇬🇧' },
  { label: 'Văn học Việt Nam', icon: '✍️' },
  { label: 'Toán học vui', icon: '🔢' },
  { label: 'Kỹ năng sống', icon: '💡' },
];

const GRADE_STRUCTURE: Record<GradeLevel, string[]> = {
  primary: ['1', '2', '3', '4', '5'],
  secondary: ['6', '7', '8', '9'],
  highschool: ['10', '11', '12'],
  advanced: ['Đại học', 'Sau đại học', 'Đi làm'],
};

const SetupView: React.FC<SetupViewProps> = ({ onStart, error, leaderboard }) => {
  const [playerName, setPlayerName] = useState('');
  const [topic, setTopic] = useState('');
  const [contentType, setContentType] = useState<ContentType>('topic');
  const [count, setCount] = useState(15);
  const [difficulty, setDifficulty] = useState<Difficulty>('medium');
  const [gradeLevel, setGradeLevel] = useState<GradeLevel>('primary');
  const [gradeClass, setGradeClass] = useState('1');
  const [bookSeries, setBookSeries] = useState<BookSeries>('none');
  const [advancedInstructions, setAdvancedInstructions] = useState('');
  const [showAdvanced, setShowAdvanced] = useState(false);

  // Cập nhật lớp học khi cấp học thay đổi
  useEffect(() => {
    setGradeClass(GRADE_STRUCTURE[gradeLevel][0]);
  }, [gradeLevel]);

  // Cập nhật số lượng mặc định khi loại nội dung thay đổi
  const handleContentTypeChange = (type: ContentType) => {
    setContentType(type);
    if (type === 'topic') {
      setCount(15);
    } else {
      setCount(10);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim() || !playerName.trim()) return;

    // Đảm bảo số lượng hợp lệ (tối thiểu theo yêu cầu)
    let finalCount = count;
    if (contentType === 'topic' && count < 15) finalCount = 15;
    if (contentType === 'lesson' && count < 10) finalCount = 10;
    if (count > 50) finalCount = 50; // Giới hạn thực tế để tránh lỗi API quá tải

    onStart({ 
      playerName, 
      topic, 
      contentType,
      count: finalCount, 
      difficulty, 
      gradeLevel, 
      gradeClass, 
      bookSeries,
      advancedInstructions 
    });
  };

  const selectTopic = (selectedTopic: string) => {
    setTopic(selectedTopic);
  };

  return (
    <div className="space-y-8">
      <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50">
        <h2 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            <span className="mr-3 text-indigo-600">✍️</span>
            Thiết lập trò chơi
        </h2>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Tên của bạn</label>
              <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">👤</span>
                  <input
                      type="text"
                      placeholder="Nhập tên..."
                      className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 transition-all outline-none text-slate-800"
                      value={playerName}
                      onChange={(e) => setPlayerName(e.target.value)}
                      required
                  />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Loại nội dung</label>
              <div className="flex bg-slate-50 p-1 rounded-2xl border-2 border-slate-100">
                <button
                  type="button"
                  onClick={() => handleContentTypeChange('topic')}
                  className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'topic' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Chủ đề (≥15 câu)
                </button>
                <button
                  type="button"
                  onClick={() => handleContentTypeChange('lesson')}
                  className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'lesson' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Bài học (≥10 câu)
                </button>
              </div>
            </div>
          </div>

          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Nội dung học tập</label>
            <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">📚</span>
                <input
                    type="text"
                    placeholder={contentType === 'topic' ? "Ví dụ: Lịch sử nhà Trần, Hải dương học..." : "Ví dụ: Bài 5 - Các nước Đông Nam Á..."}
                    className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 transition-all outline-none text-slate-800"
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                    required
                />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Cấp học</label>
              <select
                className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                value={gradeLevel}
                onChange={(e) => setGradeLevel(e.target.value as GradeLevel)}
              >
                <option value="primary">Tiểu học</option>
                <option value="secondary">THCS</option>
                <option value="highschool">THPT</option>
                <option value="advanced">Nâng cao / Đi làm</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Lớp</label>
              <select
                className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                value={gradeClass}
