import React, { useState, useRef } from 'react';
import { Question, UserAnswer } from '../types';
import confetti from 'canvas-confetti';

interface QuizEngineProps {
  questions: Question[];
  onComplete: (answers: UserAnswer[]) => void;
  onQuit: () => void;
}

const QuizEngine: React.FC<QuizEngineProps> = ({ questions, onComplete, onQuit }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const [answers, setAnswers] = useState<UserAnswer[]>([]);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);
  const [isAnswered, setIsAnswered] = useState(false);
  const [totalPoints, setTotalPoints] = useState(0);
  const [showPointsAnim, setShowPointsAnim] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const currentQuestion = questions[currentIdx];

  const playSuccessSound = () => {
    if (!audioRef.current) {
      audioRef.current = new Audio('https://assets.mixkit.co/active_storage/sfx/2013/2013-preview.mp3');
    }
    audioRef.current.currentTime = 0;
    audioRef.current.play().catch(e => console.log("Audio play failed", e));
  };

  const handleOptionSelect = (idx: number) => {
    if (isAnswered) return;
    setSelectedOption(idx);
  };

  const handleConfirm = () => {
    if (selectedOption === null) return;

    const isCorrect = selectedOption === currentQuestion.correctIndex;
    const newAnswer: UserAnswer = {
      questionIndex: currentIdx,
      selectedIndex: selectedOption,
      isCorrect
    };

    setAnswers(prev => [...prev, newAnswer]);
    setIsAnswered(true);

    if (isCorrect) {
      setTotalPoints(prev => prev + 100);
      setShowPointsAnim(true);
      playSuccessSound();
      confetti({
        particleCount: 150,
        spread: 70,
        origin: { y: 0.6 },
        colors: ['#4f46e5', '#10b981', '#fbbf24']
      });
      setTimeout(() => setShowPointsAnim(false), 1000);
    }
  };

  const handleNext = () => {
    if (currentIdx < questions.length - 1) {
      setCurrentIdx(currentIdx + 1);
      setSelectedOption(null);
      setIsAnswered(false);
    } else {
      onComplete([...answers]);
    }
  };

  const progress = ((currentIdx + (isAnswered ? 1 : 0)) / questions.length) * 100;

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100 w-full relative overflow-hidden">
      {/* Points Animation Overlay */}
      {showPointsAnim && (
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 pointer-events-none z-50">
          <div className="text-6xl font-black text-green-500 animate-points drop-shadow-lg">
            +100
          </div>
        </div>
      )}

      <div className="flex justify-between items-center mb-6">
        <div className="flex flex-col">
          <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">
            Câu hỏi {currentIdx + 1} / {questions.length}
          </span>
          <div className="flex items-center mt-1">
            <span className="text-lg font-bold text-indigo-600 mr-2">Score: {totalPoints}</span>
            <span className="text-xs font-medium text-slate-400">điểm</span>
          </div>
        </div>
        <button 
          onClick={onQuit}
          className="text-sm font-semibold text-slate-400 hover:text-red-500 transition-colors bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100"
        >
          Thoát
        </button>
      </div>

      <div className="w-full bg-slate-100 h-2 rounded-full mb-8 overflow-hidden">
        <div 
          className="h-full bg-indigo-600 transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      <h3 className="text-2xl font-bold text-slate-800 mb-8 leading-tight">
        {currentQuestion.question}
      </h3>

      <div className="space-y-4 mb-10">
        {currentQuestion.options.map((option, idx) => {
          let style = "bg-slate-50 border-2 border-slate-100 text-slate-700 hover:border-indigo-200";
          if (selectedOption === idx) {
            style = "bg-indigo-50 border-2 border-indigo-500 text-indigo-700";
          }
          if (isAnswered) {
            if (idx === currentQuestion.correctIndex) {
              style = "bg-green-50 border-2 border-green-500 text-green-700 shadow-sm shadow-green-100 scale-[1.02]";
            } else if (selectedOption === idx) {
              style = "bg-red-50 border-2 border-red-500 text-red-700";
            } else {
              style = "bg-slate-50 border-2 border-slate-100 text-slate-400 opacity-60";
            }
          }

          return (
            <button
              key={idx}
              onClick={() => handleOptionSelect(idx)}
              disabled={isAnswered}
              className={`w-full p-5 rounded-2xl text-left font-semibold transition-all duration-300 transform ${style} ${!isAnswered && 'active:scale-[0.98]'}`}
            >
              <div className="flex items-center">
                <span className={`w-8 h-8 rounded-full flex items-center justify-center mr-4 text-sm font-bold transition-colors ${selectedOption === idx ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
                  {String.fromCharCode(65 + idx)}
                </span>
                {option}
              </div>
            </button>
          );
        })}
      </div>

      {isAnswered && (
        <div className="mb-8 p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 animate-slide-in">
          <p className="text-sm text-slate-600 leading-relaxed">
            <span className="font-bold text-indigo-800 mr-2 flex items-center">
              <span className="mr-1">💡</span> Giải thích:
            </span>
            {currentQuestion.explanation}
          </p>
        </div>
      )}

      <div className="flex justify-end">
        {!isAnswered ? (
          <button
            onClick={handleConfirm}
            disabled={selectedOption === null}
            className="group relative px-10 py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-200 disabled:text-slate-400 text-white font-bold rounded-2xl shadow-lg shadow-indigo-200 transition-all active:scale-95 overflow-hidden"
          >
            <span className="relative z-10">Kiểm tra đáp án</span>
            {selectedOption !== null && (
              <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity" />
            )}
          </button>
        ) : (
          <button
            onClick={handleNext}
            className="px-10 py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-200 transition-all active:scale-95"
          >
            {currentIdx === questions.length - 1 ? 'Xem kết quả' : 'Câu tiếp theo ➔'}
          </button>
        )}
      </div>
    </div>
  );
};

export default QuizEngine;

import React from 'react';
import { Question, UserAnswer, LeaderboardEntry, QuizSetup } from '../types';
import Leaderboard from './Leaderboard';

interface ResultsViewProps {
  questions: Question[];
  answers: UserAnswer[];
  onRestart: () => void;
  setup: QuizSetup | null;
  leaderboard: LeaderboardEntry[];
}

const ResultsView: React.FC<ResultsViewProps> = ({ questions, answers, onRestart, setup, leaderboard }) => {
  const score = answers.filter(a => a.isCorrect).length;
  const totalPoints = score * 100;
  const percentage = Math.round((score / questions.length) * 100);

  let message = "Hãy tiếp tục cố gắng!";
  let icon = "🌱";
  if (percentage === 100) { message = "Điểm tuyệt đối!"; icon = "🏆"; }
  else if (percentage >= 80) { message = "Làm tốt lắm!"; icon = "🌟"; }
  else if (percentage >= 50) { message = "Khá tốt!"; icon = "👍"; }

  return (
    <div className="space-y-6 pb-12">
      <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 overflow-hidden border border-indigo-50">
        <div className="bg-indigo-600 p-10 text-center text-white">
          <div className="text-6xl mb-4">{icon}</div>
          <h2 className="text-xl font-medium opacity-80 mb-1">Chúc mừng, {setup?.playerName}!</h2>
          <p className="text-sm opacity-70 mb-4">Lớp {setup?.className} - Trường {setup?.schoolName} - {setup?.province}</p>
          <h2 className="text-3xl font-bold mb-1">{message}</h2>

          <div className="flex flex-col items-center mt-4 mb-6">
            <span className="text-5xl font-black tracking-tight">{totalPoints}</span>
            <span className="text-xs font-bold uppercase tracking-widest opacity-60">Tổng điểm tích lũy</span>
          </div>

          <p className="opacity-90 font-medium">Bạn đã trả lời đúng {score} trên {questions.length} câu</p>

          <div className="mt-8 relative inline-flex items-center justify-center">
              <svg className="w-24 h-24 transform -rotate-90">
                  <circle
                      className="text-indigo-800"
                      strokeWidth="8"
                      stroke="currentColor"
                      fill="transparent"
                      r="40"
                      cx="48"
                      cy="48"
                  />
                  <circle
                      className="text-white transition-all duration-1000 ease-out"
                      strokeWidth="8"
                      strokeDasharray={251.2}
                      strokeDashoffset={251.2 - (251.2 * percentage) / 100}
                      strokeLinecap="round"
                      stroke="currentColor"
                      fill="transparent"
                      r="40"
                      cx="48"
                      cy="48"
                  />
              </svg>
              <span className="absolute text-xl font-bold">{percentage}%</span>
          </div>
        </div>

        <div className="p-8 max-h-[400px] overflow-y-auto bg-slate-50">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex justify-between items-center">
            <span>Xem lại đáp án</span>
            <span className="text-xs font-normal text-slate-500 italic">Dành cho {setup?.topic}</span>
          </h3>
          <div className="space-y-4">
            {questions.map((q, idx) => {
              const userAnswer = answers.find(a => a.questionIndex === idx);
              return (
                <div key={idx} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm">
                  <div className="flex items-start mb-3">
                      <span className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center mr-3 mt-0.5 ${userAnswer?.isCorrect ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                          {userAnswer?.isCorrect ? '✓' : '✕'}
                      </span>
                      <p className="font-semibold text-slate-800">{q.question}</p>
                  </div>
                  {!userAnswer?.isCorrect && (
                      <p className="text-sm text-slate-500 ml-9">
                          Đáp án đúng: <span className="font-bold text-green-600">{q.options[q.correctIndex]}</span>
                      </p>
                  )}
                </div>
              );
            })}
          </div>
        </div>

        <div className="p-8 bg-white border-t border-slate-100">
          <button
            onClick={onRestart}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-2xl shadow-lg shadow-indigo-100 transition-all active:scale-95"
          >
            Làm bộ câu hỏi khác
          </button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100">
        <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center">
          <span className="mr-3 text-yellow-500">🏆</span>
          Bảng xếp hạng vinh danh
        </h2>
        <Leaderboard entries={leaderboard} />
      </div>
    </div>
  );
};

export default ResultsView;

import React, { useState, useEffect } from 'react';
import { AppState, Question, QuizSetup, UserAnswer, LeaderboardEntry } from './types';
import { generateQuiz } from './services/geminiService';
import SetupView from './components/SetupView';
import QuizEngine from './components/QuizEngine';
import ResultsView from './components/ResultsView';
import LoadingView from './components/LoadingView';

const LEADERBOARD_KEY = 'brainboost_leaderboard_v2';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.SETUP);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [currentSetup, setCurrentSetup] = useState<QuizSetup | null>(null);
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem(LEADERBOARD_KEY);
    if (saved) {
      try {
        setLeaderboard(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load leaderboard");
      }
    }
  }, []);

  const saveScore = (setup: QuizSetup, score: number, total: number) => {
    const newEntry: LeaderboardEntry = {
      id: Math.random().toString(36).substr(2, 9),
      playerName: setup.playerName,
      schoolName: setup.schoolName,
      className: setup.className,
      province: setup.province,
      score,
      total,
      topic: setup.topic,
      date: Date.now()
    };
    const updated = [newEntry, ...leaderboard]
      .sort((a, b) => (b.score / b.total) - (a.score / a.total) || b.date - a.date)
      .slice(0, 15); // Lưu top 15

    setLeaderboard(updated);
    localStorage.setItem(LEADERBOARD_KEY, JSON.stringify(updated));
  };

  const startQuiz = async (setup: QuizSetup) => {
    setState(AppState.LOADING);
    setError(null);
    setCurrentSetup(setup);
    try {
      const generatedQuestions = await generateQuiz(setup);
      if (generatedQuestions.length === 0) {
        throw new Error("Không có câu hỏi nào được tạo ra.");
      }
      setQuestions(generatedQuestions);
      setUserAnswers([]);
      setState(AppState.PLAYING);
    } catch (err: any) {
      setError(err.message || "Đã xảy ra lỗi không mong muốn");
      setState(AppState.SETUP);
    }
  };

  const handleComplete = (answers: UserAnswer[]) => {
    setUserAnswers(answers);
    const score = answers.filter(a => a.isCorrect).length;
    if (currentSetup) {
      saveScore(currentSetup, score, questions.length);
    }
    setState(AppState.RESULTS);
  };

  const reset = () => {
    setState(AppState.SETUP);
    // Giữ lại currentSetup để SetupView có thể sử dụng lại dữ liệu cũ nếu muốn đổi chủ đề
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  const renderContent = () => {
    switch (state) {
      case AppState.SETUP:
        return <SetupView onStart={startQuiz} error={error} leaderboard={leaderboard} initialSetup={currentSetup} />;
      case AppState.LOADING:
        return <LoadingView onCancel={reset} />;
      case AppState.PLAYING:
        return (
          <QuizEngine 
            questions={questions} 
            onComplete={handleComplete} 
            onQuit={reset}
          />
        );
      case AppState.RESULTS:
        return (
          <ResultsView 
            questions={questions} 
            answers={userAnswers} 
            onRestart={reset}
            setup={currentSetup}
            leaderboard={leaderboard}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-start py-8 px-4 sm:px-6 lg:px-8">
      <div className="w-full max-w-2xl">
        <header className="text-center mb-8">
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight mb-2">
            HỌC <span className="text-indigo-600">THÔNG MINH</span>
          </h1>
          <p className="text-slate-500 font-medium italic">Học tập thông minh - Khẳng định tài năng</p>
        </header>

        <main className="animate-slide-in">
          {renderContent()}
        </main>
      </div>

      <footer className="mt-12 text-slate-400 text-sm text-center">
        &copy; {new Date().getFullYear()} HỌC THÔNG MINH - Nền tảng học tập AI.
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { QuizSetup, Difficulty, LeaderboardEntry, GradeLevel, BookSeries, ContentType } from '../types';
import Leaderboard from './Leaderboard';

interface SetupViewProps {
  onStart: (setup: QuizSetup) => void;
  error: string | null;
  leaderboard: LeaderboardEntry[];
  initialSetup?: QuizSetup | null;
}

const PREDEFINED_TOPICS = [
  { label: 'Lịch sử Việt Nam', icon: '🇻🇳' },
  { label: 'Địa lý thế giới', icon: '🌍' },
  { label: 'Khoa học & Vũ trụ', icon: '🚀' },
  { label: 'Lập trình React', icon: '💻' },
  { label: 'Tiếng Anh giao tiếp', icon: '🇬🇧' },
  { label: 'Văn học Việt Nam', icon: '✍️' },
  { label: 'Toán học vui', icon: '🔢' },
  { label: 'Kỹ năng sống', icon: '💡' },
];

const GRADE_STRUCTURE: Record<GradeLevel, string[]> = {
  primary: ['1', '2', '3', '4', '5'],
  secondary: ['6', '7', '8', '9'],
  highschool: ['10', '11', '12'],
  advanced: ['Đại học', 'Sau đại học', 'Đi làm'],
};

const SetupView: React.FC<SetupViewProps> = ({ onStart, error, leaderboard, initialSetup }) => {
  const [playerName, setPlayerName] = useState(initialSetup?.playerName || '');
  const [topic, setTopic] = useState(initialSetup?.topic || '');
  const [contentType, setContentType] = useState<ContentType>(initialSetup?.contentType || 'topic');
  const [count, setCount] = useState(initialSetup?.count || 15);
  const [difficulty, setDifficulty] = useState<Difficulty>(initialSetup?.difficulty || 'medium');
  const [gradeLevel, setGradeLevel] = useState<GradeLevel>(initialSetup?.gradeLevel || 'primary');
  const [gradeNumber, setGradeNumber] = useState(initialSetup?.gradeNumber || '1');
  const [className, setClassName] = useState(initialSetup?.className || '');
  const [schoolName, setSchoolName] = useState(initialSetup?.schoolName || '');
  const [commune, setCommune] = useState(initialSetup?.commune || '');
  const [province, setProvince] = useState(initialSetup?.province || '');
  const [bookSeries, setBookSeries] = useState<BookSeries>(initialSetup?.bookSeries || 'none');
  const [advancedInstructions, setAdvancedInstructions] = useState(initialSetup?.advancedInstructions || '');
  const [showAdvanced, setShowAdvanced] = useState(!!initialSetup?.advancedInstructions);

  useEffect(() => {
    if (!initialSetup) {
      setGradeNumber(GRADE_STRUCTURE[gradeLevel][0]);
    }
  }, [gradeLevel, initialSetup]);

  const handleContentTypeChange = (type: ContentType) => {
    setContentType(type);
    if (type === 'topic' && count < 15) {
      setCount(15);
    } else if (type === 'lesson' && count < 10) {
      setCount(10);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim() || !playerName.trim()) return;

    let finalCount = count;
    if (contentType === 'topic' && count < 15) finalCount = 15;
    if (contentType === 'lesson' && count < 10) finalCount = 10;
    if (count > 50) finalCount = 50;

    onStart({ 
      playerName, 
      topic, 
      contentType,
      count: finalCount, 
      difficulty, 
      gradeLevel, 
      gradeNumber,
      className: className || `${gradeNumber}...`,
      schoolName: schoolName || 'Tự do',
      commune: commune || 'N/A',
      province: province || 'Việt Nam',
      bookSeries,
      advancedInstructions 
    });
  };

  const selectTopic = (selectedTopic: string) => {
    setTopic(selectedTopic);
  };

  return (
    <div className="space-y-8 pb-12">
      <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50">
        <h2 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            <span className="mr-3 text-indigo-600">✍️</span>
            {initialSetup ? 'Đổi chủ đề học tập' : 'Thiết lập người chơi & Bài học'}
        </h2>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Section: Thông tin cá nhân */}
          <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100 space-y-4">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">Thông tin cá nhân</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Họ và tên</label>
                <input
                    type="text"
                    placeholder="Nhập tên..."
                    className="w-full px-5 py-4 bg-white border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 outline-none text-slate-800"
                    value={playerName}
                    onChange={(e) => setPlayerName(e.target.value)}
                    required
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Tên lớp (ví dụ: 12A1)</label>
                <input
                    type="text"
                    placeholder="Lớp..."
                    className="w-full px-5 py-4 bg-white border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 outline-none text-slate-800"
                    value={className}
                    onChange={(e) => setClassName(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Trường học</label>
              <input
                  type="text"
                  placeholder="Tên trường..."
                  className="w-full px-5 py-4 bg-white border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 outline-none text-slate-800"
                  value={schoolName}
                  onChange={(e) => setSchoolName(e.target.value)}
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Xã/Phường</label>
                <input
                    type="text"
                    placeholder="Xã/Phường..."
                    className="w-full px-5 py-4 bg-white border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 outline-none text-slate-800"
                    value={commune}
                    onChange={(e) => setCommune(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Tỉnh/Thành phố</label>
                <input
                    type="text"
                    placeholder="Tỉnh/Thành..."
                    className="w-full px-5 py-4 bg-white border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 outline-none text-slate-800"
                    value={province}
                    onChange={(e) => setProvince(e.target.value)}
                />
              </div>
            </div>
          </div>

          {/* Section: Nội dung học tập */}
          <div className="space-y-4">
            <div className="flex bg-slate-50 p-1 rounded-2xl border-2 border-slate-100">
              <button
                type="button"
                onClick={() => handleContentTypeChange('topic')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'topic' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Chủ đề (≥15 câu)
              </button>
              <button
                type="button"
                onClick={() => handleContentTypeChange('lesson')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'lesson' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Bài học (≥10 câu)
              </button>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Nội dung học tập</label>
              <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">📚</span>
                  <input
                      type="text"
                      placeholder={contentType === 'topic' ? "Ví dụ: Lịch sử nhà Trần, Hải dương học..." : "Ví dụ: Bài 5 - Các nước Đông Nam Á..."}
                      className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 transition-all outline-none text-slate-800"
                      value={topic}
                      onChange={(e) => setTopic(e.target.value)}
                      required
                  />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Cấp học</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={gradeLevel}
                  onChange={(e) => setGradeLevel(e.target.value as GradeLevel)}
                >
                  <option value="primary">Tiểu học</option>
                  <option value="secondary">THCS</option>
                  <option value="highschool">THPT</option>
                  <option value="advanced">Khác / Đi làm</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Khối</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={gradeNumber}
                  onChange={(e) => setGradeNumber(e.target.value)}
                >
                  {GRADE_STRUCTURE[gradeLevel].map(c => (
                    <option key={c} value={c}>{gradeLevel === 'advanced' ? c : `Khối ${c}`}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Bộ sách giáo khoa</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={bookSeries}
                  onChange={(e) => setBookSeries(e.target.value as BookSeries)}
                >
                  <option value="none">Mặc định / Khác</option>
                  <option value="canh_dieu">Cánh diều</option>
                  <option value="ket_noi_tri_thuc">Kết nối tri thức</option>
                  <option value="chan_troi_sang_tao">Chân trời sáng tạo</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Số câu hỏi</label>
                <div className="relative">
                  <input
                      type="number"
                      min={contentType === 'topic' ? 15 : 10}
                      max={50}
                      className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 font-bold"
                      value={count}
                      onChange={(e) => setCount(parseInt(e.target.value) || 0)}
                  />
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs text-slate-400 font-bold">CÂU</span>
                </div>
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Độ khó</label>
              <div className="grid grid-cols-3 gap-2">
                {(['easy', 'medium', 'hard'] as Difficulty[]).map((d) => (
                  <button
                    key={d}
                    type="button"
                    onClick={() => setDifficulty(d)}
                    className={`py-3 rounded-2xl text-xs font-bold transition-all border-2 ${
                      difficulty === d 
                      ? 'bg-indigo-600 text-white border-indigo-600 shadow-md scale-105' 
                      : 'bg-white text-slate-500 border-slate-100 hover:border-indigo-200'
                    }`}
                  >
                    {d === 'easy' ? 'DỄ' : d === 'medium' ? 'VỪA' : 'KHÓ'}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div>
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Gợi ý nhanh chủ đề:</span>
            <div className="flex flex-wrap gap-2">
              {PREDEFINED_TOPICS.map((t) => (
                <button
                  key={t.label}
                  type="button"
                  onClick={() => selectTopic(t.label)}
                  className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                    topic === t.label 
                      ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
                      : 'bg-white text-slate-600 border-slate-200 hover:border-indigo-300 hover:bg-indigo-50'
                  }`}
                >
                  <span className="mr-1">{t.icon}</span> {t.label}
                </button>
              ))}
            </div>
          </div>

          <div>
            <button 
                type="button" 
                onClick={() => setShowAdvanced(!showAdvanced)}
                className="text-indigo-600 text-sm font-semibold flex items-center hover:text-indigo-700 transition-colors"
            >
                {showAdvanced ? '− Thu gọn yêu cầu nâng cao' : '+ Thêm yêu cầu nâng cao (tùy chọn)'}
            </button>

            {showAdvanced && (
                <div className="mt-4 animate-slide-in">
                    <label className="block text-sm font-semibold text-slate-700 mb-2">Hướng dẫn bổ sung cho AI</label>
                    <textarea
                        placeholder="Ví dụ: Tập trung vào các mốc thời gian, bỏ qua các câu hỏi lý thuyết suông..."
                        className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-0 transition-all outline-none text-slate-800 min-h-[100px]"
                        value={advancedInstructions}
                        onChange={(e) => setAdvancedInstructions(e.target.value)}
                    />
                </div>
            )}
          </div>

