import { GoogleGenAI, Type } from "@google/genai";
import { Question, QuizSetup } from "../types";

export const generateQuiz = async (setup: QuizSetup): Promise<Question[]> => {
  // Use API_KEY directly as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const gradeNames: Record<string, string> = {
    primary: 'Tiểu học',
    secondary: 'Trung học cơ sở',
    highschool: 'Trung học phổ thông',
    advanced: 'Đại học / Người đi làm'
  };

  const bookSeriesNames: Record<string, string> = {
    canh_dieu: 'Cánh diều',
    ket_noi_tri_thuc: 'Kết nối tri thức với cuộc sống',
    chan_troi_sang_tao: 'Chân trời sáng tạo',
    none: 'Chương trình chuẩn'
  };

  const typeDesc = setup.contentType === 'topic' ? 'theo chủ đề rộng' : 'theo một bài học cụ thể';

  // Thông tin ngữ cảnh học sinh
  const studentContext = `Học sinh lớp ${setup.className}, khối ${setup.gradeNumber} (${gradeNames[setup.gradeLevel]}), trường ${setup.schoolName}, tỉnh ${setup.province}.`;

  let prompt = `Hãy tạo một bộ câu hỏi trắc nghiệm ${typeDesc} về: "${setup.topic}". 
  Tất cả nội dung (câu hỏi, các lựa chọn, giải thích) PHẢI bằng tiếng Việt.

  ĐỐI TƯỢNG: ${studentContext}
  BỘ SÁCH GIÁO KHOA: ${bookSeriesNames[setup.bookSeries]}.
  Mức độ khó là ${setup.difficulty === 'easy' ? 'dễ' : setup.difficulty === 'medium' ? 'trung bình' : 'khó'}. 

  Cung cấp đúng CHÍNH XÁC ${setup.count} câu hỏi trắc nghiệm chất lượng cao. 
  Đảm bảo nội dung bám sát chương trình học và tính chất của ${setup.contentType === 'topic' ? 'một chủ đề tổng quát' : 'một bài học chi tiết'}.
  Mỗi câu hỏi phải có đúng 4 lựa chọn. 
  Bao gồm một lời giải thích ngắn gọn, súc tích và chính xác.`;

  if (setup.advancedInstructions && setup.advancedInstructions.trim() !== "") {
    prompt += `\n\nLƯU Ý NÂNG CAO TỪ NGƯỜI DÙNG: "${setup.advancedInstructions}". 
    Hãy điều chỉnh nội dung câu hỏi để tuân thủ nghiêm ngặt các yêu cầu bổ sung này.`;
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING },
              description: "Mảng chứa đúng 4 chuỗi đại diện cho các lựa chọn trả lời."
            },
            correctIndex: { 
              type: Type.INTEGER,
              description: "Chỉ số (0-based) của đáp án đúng."
            },
            explanation: { type: Type.STRING }
          },
          required: ["question", "options", "correctIndex", "explanation"],
        },
      },
    },
  });

  try {
    const text = response.text || '[]';
    const questions: Question[] = JSON.parse(text);
    return questions;
  } catch (error) {
    console.error("Lỗi khi phân tích JSON câu hỏi:", error);
    throw new Error("Không thể tạo dữ liệu trắc nghiệm. Vui lòng thử lại với số lượng câu hỏi ít hơn hoặc chủ đề rõ ràng hơn.");
  }
};

