          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-4">
            <div className="flex bg-slate-50 p-1 rounded-2xl border-2 border-slate-100">
              <button
                type="button"
                onClick={() => handleContentTypeChange('topic')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'topic' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Chủ đề tổng quát
              </button>
              <button
                type="button"
                onClick={() => handleContentTypeChange('lesson')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'lesson' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
