                    {contentType === 'topic' ? '🌍' : '📖'}
                  </span>
                  <input
                      type="text"
                      placeholder={contentType === 'topic' ? "Ví dụ: Lịch sử nhà Trần, Hải dương học..." : "Ví dụ: Bài 5 - Các nước Đông Nam Á..."}
