import React, { useState, useEffect, useRef } from 'react';
import { QuizSetup, Difficulty, LeaderboardEntry, GradeLevel, BookSeries, ContentType, UserProfile, FileData } from '../types';
import Leaderboard from './Leaderboard';

interface SetupViewProps {
  onStart: (setup: QuizSetup) => void;
  error: string | null;
  leaderboard: LeaderboardEntry[];
  initialSetup?: QuizSetup | null;
  userProfile: UserProfile | null;
  onLogout: () => void;
}

const PREDEFINED_TOPICS = [
  { label: 'Lịch sử Việt Nam', icon: '🇻🇳' },
  { label: 'Địa lý thế giới', icon: '🌍' },
  { label: 'Khoa học & Vũ trụ', icon: '🚀' },
  { label: 'Lập trình React', icon: '💻' },
  { label: 'Tiếng Anh giao tiếp', icon: '🇬🇧' },
  { label: 'Văn học Việt Nam', icon: '✍️' },
  { label: 'Toán học vui', icon: '🔢' },
  { label: 'Kỹ năng sống', icon: '💡' },
];

const PREDEFINED_SUBJECTS = [
  'Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý', 'Tin học', 'GDCD'
];

const GRADE_STRUCTURE: Record<GradeLevel, string[]> = {
  primary: ['1', '2', '3', '4', '5'],
  secondary: ['6', '7', '8', '9'],
  highschool: ['10', '11', '12'],
  advanced: ['Đại học', 'Sau đại học', 'Đi làm'],
};

const SetupView: React.FC<SetupViewProps> = ({ onStart, error, leaderboard, initialSetup, userProfile, onLogout }) => {
  const [subject, setSubject] = useState('');
  const [topic, setTopic] = useState(initialSetup?.topic || '');
  const [contentType, setContentType] = useState<ContentType>(initialSetup?.contentType || 'topic');
  const [count, setCount] = useState(initialSetup?.count || 15);
  const [difficulty, setDifficulty] = useState<Difficulty>(initialSetup?.difficulty || 'medium');
  const [gradeNumber, setGradeNumber] = useState(initialSetup?.gradeNumber || userProfile?.gradeNumber || '1');
  const [bookSeries, setBookSeries] = useState<BookSeries>(initialSetup?.bookSeries || 'none');
  const [advancedInstructions, setAdvancedInstructions] = useState(initialSetup?.advancedInstructions || '');
  const [showAdvanced, setShowAdvanced] = useState(!!initialSetup?.advancedInstructions);
  const [fileData, setFileData] = useState<FileData | undefined>(initialSetup?.fileData);
  const [fileName, setFileName] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!initialSetup && userProfile) {
      setGradeNumber(GRADE_STRUCTURE[userProfile.gradeLevel][0]);
    }
  }, [userProfile, initialSetup]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFileName(file.name);
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setFileData({
          data: base64String,
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeFile = () => {
    setFileData(undefined);
    setFileName('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleContentTypeChange = (type: ContentType) => {
    setContentType(type);
    if (type === 'topic' && count < 15) {
      setCount(15);
    } else if (type === 'lesson' && count < 10) {
      setCount(10);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userProfile) return;

    // Nếu không có tệp thì yêu cầu topic, nếu có tệp thì topic có thể là gợi ý hoặc để trống
    if (!topic.trim() && !fileData) return;

    let finalCount = count;
    if (contentType === 'topic' && count < 15) finalCount = 15;
    if (contentType === 'lesson' && count < 10) finalCount = 10;
    if (count > 50) finalCount = 50;

    const finalTopic = subject ? `${subject}: ${topic}` : (topic || 'Dựa trên tài liệu đã tải lên');

    onStart({ 
      playerName: userProfile.playerName, 
      topic: finalTopic, 
      contentType,
      count: finalCount, 
      difficulty, 
      gradeLevel: userProfile.gradeLevel, 
      gradeNumber,
      className: userProfile.className,
      schoolName: userProfile.schoolName,
      province: userProfile.province,
      bookSeries,
      advancedInstructions,
      fileData
    });
  };

  const selectTopic = (selectedTopic: string) => {
    setTopic(selectedTopic);
    setSubject('');
  };

  return (
    <div className="space-y-8 pb-12 animate-slide-in">
      {/* Header Profile */}
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex justify-between items-center">
        <div>
          <p className="text-indigo-100 text-xs font-bold uppercase tracking-widest">Đang học tập</p>
          <h3 className="text-xl font-bold">{userProfile?.playerName}</h3>
          <p className="text-sm opacity-80">{userProfile?.className} - {userProfile?.schoolName}</p>
        </div>
        <button 
          onClick={onLogout}
          className="bg-white/10 hover:bg-white/20 p-3 rounded-2xl transition-all text-xs font-bold"
        >
          Đăng xuất
        </button>
      </div>

      <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50">
        <h2 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            <span className="mr-3 text-indigo-600">🎯</span>
            Thiết lập nội dung bài học
        </h2>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Section: Upload Tài liệu */}
          <div className="space-y-3">
            <label className="block text-sm font-semibold text-slate-700">Tải ảnh bài học hoặc tài liệu (Tùy chọn)</label>
            <div 
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer ${fileData ? 'border-green-400 bg-green-50' : 'border-slate-200 hover:border-indigo-400 hover:bg-indigo-50/30'}`}
            >
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*,.pdf,.txt"
              />
              {!fileData ? (
                <div className="space-y-2">
                  <div className="text-3xl">📁</div>
                  <div className="text-sm font-medium text-slate-600">Nhấn để tải lên tài liệu học tập</div>
                  <div className="text-[10px] text-slate-400 uppercase tracking-widest">Hỗ trợ Ảnh, PDF, TXT</div>
                </div>
              ) : (
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="text-2xl">✅</div>
                    <div className="text-left">
                      <div className="text-sm font-bold text-green-700 truncate max-w-[200px]">{fileName}</div>
                      <div className="text-[10px] text-green-600">Tài liệu đã sẵn sàng để AI phân tích</div>
                    </div>
                  </div>
                  <button 
                    type="button" 
                    onClick={(e) => { e.stopPropagation(); removeFile(); }}
                    className="p-2 hover:bg-red-100 rounded-lg text-red-500 transition-colors"
                  >
                    ✕
                  </button>
                </div>
              )}
            </div>
            {fileData && (
              <p className="text-[11px] text-indigo-500 font-medium italic">* AI sẽ tự động tạo câu hỏi dựa trên nội dung tệp này.</p>
            )}
          </div>

          <div className="space-y-4">
            <div className="flex bg-slate-50 p-1 rounded-2xl border-2 border-slate-100">
              <button
                type="button"
                onClick={() => handleContentTypeChange('topic')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'topic' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Chủ đề tổng quát
              </button>
              <button
                type="button"
                onClick={() => handleContentTypeChange('lesson')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'lesson' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Bài học cụ thể
              </button>
            </div>

            {contentType === 'lesson' && (
              <div className="animate-slide-in">
                <label className="block text-sm font-semibold text-slate-700 mb-2">Chọn Môn học</label>
                <div className="flex flex-wrap gap-2 mb-4">
                  {PREDEFINED_SUBJECTS.map(s => (
                    <button
                      key={s}
                      type="button"
                      onClick={() => setSubject(s)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${
                        subject === s 
                        ? 'bg-indigo-100 text-indigo-700 border-indigo-300' 
                        : 'bg-white text-slate-500 border-slate-100 hover:border-indigo-200'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">
                {contentType === 'topic' ? 'Tên Chủ đề' : 'Tên Bài học'}
              </label>
              <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                    {contentType === 'topic' ? '🌍' : '📖'}
                  </span>
                  <input
                      type="text"
                      placeholder={contentType === 'topic' ? "Ví dụ: Lịch sử nhà Trần, Hải dương học..." : "Ví dụ: Bài 5 - Các nước Đông Nam Á..."}
                      className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800"
                      value={topic}
                      onChange={(e) => setTopic(e.target.value)}
                      required={!fileData}
                  />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Khối lớp hiện tại</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={gradeNumber}
                  onChange={(e) => setGradeNumber(e.target.value)}
                >
                  {userProfile && GRADE_STRUCTURE[userProfile.gradeLevel].map(c => (
                    <option key={c} value={c}>{userProfile.gradeLevel === 'advanced' ? c : `Khối ${c}`}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Số câu hỏi</label>
                <div className="relative">
                  <input
                      type="number"
                      min={contentType === 'topic' ? 15 : 10}
                      max={50}
                      className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 font-bold"
                      value={count}
                      onChange={(e) => setCount(parseInt(e.target.value) || 0)}
                  />
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs text-slate-400 font-bold">CÂU</span>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Bộ sách giáo khoa</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={bookSeries}
                  onChange={(e) => setBookSeries(e.target.value as BookSeries)}
                >
                  <option value="none">Mặc định / Khác</option>
                  <option value="canh_dieu">Cánh diều</option>
                  <option value="ket_noi_tri_thuc">Kết nối tri thức</option>
                  <option value="chan_troi_sang_tao">Chân trời sáng tạo</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Độ khó</label>
                <div className="grid grid-cols-3 gap-2">
                  {(['easy', 'medium', 'hard'] as Difficulty[]).map((d) => (
                    <button
                      key={d}
                      type="button"
                      onClick={() => setDifficulty(d)}
                      className={`py-3 rounded-2xl text-[10px] font-bold transition-all border-2 ${
                        difficulty === d 
                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
                        : 'bg-white text-slate-500 border-slate-100 hover:border-indigo-200'
                      }`}
                    >
                      {d === 'easy' ? 'DỄ' : d === 'medium' ? 'VỪA' : 'KHÓ'}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {contentType === 'topic' && (
            <div>
              <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Gợi ý nhanh chủ đề:</span>
              <div className="flex flex-wrap gap-2">
                {PREDEFINED_TOPICS.map((t) => (
                  <button
                    key={t.label}
                    type="button"
                    onClick={() => selectTopic(t.label)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                      topic === t.label 
                        ? 'bg-indigo-600 text-white border-indigo-600' 
                        : 'bg-white text-slate-600 border-slate-200 hover:border-indigo-300'
                    }`}
                  >
                    <span className="mr-1">{t.icon}</span> {t.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div>
            <button 
                type="button" 
                onClick={() => setShowAdvanced(!showAdvanced)}
                className="text-indigo-600 text-sm font-semibold flex items-center hover:text-indigo-700 transition-colors"
            >
                {showAdvanced ? '− Thu gọn yêu cầu nâng cao' : '+ Thêm yêu cầu nâng cao (tùy chọn)'}
            </button>

            {showAdvanced && (
                <div className="mt-4 animate-slide-in">
                    <textarea
                        placeholder="Ví dụ: Tập trung vào các mốc thời gian, bỏ qua các câu hỏi lý thuyết suông..."
                        className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 min-h-[100px]"
                        value={advancedInstructions}
                        onChange={(e) => setAdvancedInstructions(e.target.value)}
                    />
                </div>
            )}
          </div>

          <button
            type="submit"
            disabled={!topic.trim() && !fileData}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-bold py-5 rounded-2xl transition-all shadow-lg shadow-indigo-200 mt-4 active:scale-95"
          >
            {initialSetup ? 'Cập nhật & Bắt đầu lại' : 'Bắt đầu bài trắc nghiệm'}
          </button>
        </form>
      </div>

      {leaderboard.length > 0 && (
          <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100">
              <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center">
                <span className="mr-3 text-yellow-500">🏆</span>
                Bảng xếp hạng vinh danh
              </h2>
              <Leaderboard entries={leaderboard} />
          </div>
      )}
    </div>
  );
};

export default SetupView;

import { GoogleGenAI, Type } from "@google/genai";
import { Question, QuizSetup } from "../types";

export const generateQuiz = async (setup: QuizSetup): Promise<Question[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const gradeNames: Record<string, string> = {
    primary: 'Tiểu học',
    secondary: 'Trung học cơ sở',
    highschool: 'Trung học thông phổ',
    advanced: 'Đại học / Người đi làm'
  };

  const bookSeriesNames: Record<string, string> = {
    canh_dieu: 'Cánh diều',
    ket_noi_tri_thuc: 'Kết nối tri thức với cuộc sống',
    chan_troi_sang_tao: 'Chân trời sáng tạo',
    none: 'Chương trình chuẩn'
  };

  const typeDesc = setup.contentType === 'topic' ? 'theo chủ đề rộng' : 'theo một bài học cụ thể';
  const studentContext = `Học sinh lớp ${setup.className}, khối ${setup.gradeNumber} (${gradeNames[setup.gradeLevel]}), trường ${setup.schoolName}, tỉnh ${setup.province}.`;

  let prompt = `Bạn là một chuyên gia giáo dục AI. Hãy tạo một bộ câu hỏi trắc nghiệm ${typeDesc}. 
  Tất cả nội dung (câu hỏi, các lựa chọn, giải thích) PHẢI bằng tiếng Việt.

  ĐỐI TƯỢNG: ${studentContext}
  BỘ SÁCH GIÁO KHOA: ${bookSeriesNames[setup.bookSeries]}.
  MỨC ĐỘ KHÓ: ${setup.difficulty === 'easy' ? 'Dễ' : setup.difficulty === 'medium' ? 'Trung bình' : 'Khó'}. 
  SỐ CÂU HỎI: ${setup.count}.`;

  if (setup.fileData) {
    prompt += `\n\nQUAN TRỌNG: Hãy trích xuất kiến thức từ hình ảnh/tài liệu đính kèm để đặt câu hỏi. Đảm bảo câu hỏi bám sát nội dung trong tài liệu này.`;
  }

  prompt += `\nCHỦ ĐỀ/YÊU CẦU: "${setup.topic}".`;

  if (setup.advancedInstructions && setup.advancedInstructions.trim() !== "") {
    prompt += `\nLƯU Ý NÂNG CAO: "${setup.advancedInstructions}".`;
  }

  prompt += `\n\nYÊU CẦU ĐỊNH DẠNG:
  - Mỗi câu hỏi có đúng 4 lựa chọn.
  - Phải có giải thích ngắn gọn tại sao đáp án đó đúng.
  - Phải trả về mảng JSON đúng cấu trúc.`;

  const parts: any[] = [{ text: prompt }];

  if (setup.fileData) {
    parts.push({
      inlineData: {
        data: setup.fileData.data,
        mimeType: setup.fileData.mimeType
      }
    });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            question: { type: Type.STRING },
            options: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING }
            },
            correctIndex: { type: Type.INTEGER },
            explanation: { type: Type.STRING }
          },
          required: ["question", "options", "correctIndex", "explanation"],
        },
      },
    },
  });

  try {
    const text = response.text || '[]';
    return JSON.parse(text);
  } catch (error) {
    console.error("Lỗi phân tích JSON:", error);
    throw new Error("Không thể tạo câu hỏi từ tài liệu này. Hãy thử tải ảnh rõ nét hơn hoặc cung cấp chủ đề cụ thể.");
  }
};

