import React, { useState, useEffect } from 'react';
import { AppState, Question, QuizSetup, UserAnswer, LeaderboardEntry, UserProfile } from './types';
import { generateQuiz } from './services/geminiService';
import SetupView from './components/SetupView';
import QuizEngine from './components/QuizEngine';
import ResultsView from './components/ResultsView';
import LoadingView from './components/LoadingView';
import AuthView from './components/AuthView';

const LEADERBOARD_KEY = 'brainboost_leaderboard_v2';
const USERS_KEY = 'brainboost_users_v1';
const CURRENT_USER_KEY = 'brainboost_current_user';
const LAST_SETUP_KEY = 'brainboost_last_setup';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.AUTH);
  const [isInitializing, setIsInitializing] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [currentSetup, setCurrentSetup] = useState<QuizSetup | null>(null);
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // 1. Tải bảng xếp hạng
    const savedLeaderboard = localStorage.getItem(LEADERBOARD_KEY);
    if (savedLeaderboard) {
      try { setLeaderboard(JSON.parse(savedLeaderboard)); } catch (e) {}
    }

    // 2. Kiểm tra phiên đăng nhập cũ
    const savedUser = localStorage.getItem(CURRENT_USER_KEY);
    if (savedUser) {
      try {
        const user = JSON.parse(savedUser);
        setCurrentUser(user);

        // 3. Tải thiết lập học tập gần nhất để "vào học ngay"
        const savedSetup = localStorage.getItem(LAST_SETUP_KEY);
        if (savedSetup) {
          setCurrentSetup(JSON.parse(savedSetup));
        }

        setState(AppState.SETUP);
      } catch (e) {
        localStorage.removeItem(CURRENT_USER_KEY);
      }
    }

    setIsInitializing(false);
  }, []);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    setState(AppState.SETUP);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentSetup(null);
    localStorage.removeItem(CURRENT_USER_KEY);
    localStorage.removeItem(LAST_SETUP_KEY);
    setState(AppState.AUTH);
  };

  const saveScore = (setup: QuizSetup, score: number, total: number) => {
    const newEntry: LeaderboardEntry = {
      id: Math.random().toString(36).substr(2, 9),
      playerName: setup.playerName,
      schoolName: setup.schoolName,
      className: setup.className,
      province: setup.province,
      score,
      total,
      topic: setup.topic,
      date: Date.now()
    };
    const updated = [newEntry, ...leaderboard]
      .sort((a, b) => (b.score / b.total) - (a.score / a.total) || b.date - a.date)
      .slice(0, 15);

    setLeaderboard(updated);
    localStorage.setItem(LEADERBOARD_KEY, JSON.stringify(updated));
  };

  const startQuiz = async (setup: QuizSetup) => {
    setState(AppState.LOADING);
    setError(null);
    setCurrentSetup(setup);

    // Lưu thiết lập này để lần sau không phải nhập lại
    localStorage.setItem(LAST_SETUP_KEY, JSON.stringify(setup));

    try {
      const generatedQuestions = await generateQuiz(setup);
      if (generatedQuestions.length === 0) {
        throw new Error("Không có câu hỏi nào được tạo ra.");
      }
      setQuestions(generatedQuestions);
      setUserAnswers([]);
      setState(AppState.PLAYING);
    } catch (err: any) {
      setError(err.message || "Đã xảy ra lỗi không mong muốn");
      setState(AppState.SETUP);
    }
  };

  const handleComplete = (answers: UserAnswer[]) => {
    setUserAnswers(answers);
    const score = answers.filter(a => a.isCorrect).length;
    if (currentSetup) {
      saveScore(currentSetup, score, questions.length);
    }
    setState(AppState.RESULTS);
  };

  const reset = () => {
    setState(AppState.SETUP);
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="animate-pulse flex flex-col items-center">
          <div className="w-12 h-12 bg-indigo-600 rounded-2xl mb-4"></div>
          <p className="text-slate-400 font-medium">Đang khởi động...</p>
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch (state) {
      case AppState.AUTH:
        return <AuthView onLogin={handleLogin} />;
      case AppState.SETUP:
        return (
          <SetupView 
            onStart={startQuiz} 
            error={error} 
            leaderboard={leaderboard} 
            initialSetup={currentSetup}
            userProfile={currentUser}
            onLogout={handleLogout}
          />
        );
      case AppState.LOADING:
        return <LoadingView onCancel={reset} />;
      case AppState.PLAYING:
        return (
          <QuizEngine 
            questions={questions} 
            onComplete={handleComplete} 
            onQuit={reset}
          />
        );
      case AppState.RESULTS:
        return (
          <ResultsView 
            questions={questions} 
            answers={userAnswers} 
            onRestart={reset}
            setup={currentSetup}
            leaderboard={leaderboard}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-start py-8 px-4 sm:px-6 lg:px-8">
      <div className="w-full max-w-2xl">
        <header className="text-center mb-8">
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight mb-2">
            HỌC <span className="text-indigo-600">THÔNG MINH</span>
          </h1>
          <p className="text-slate-500 font-medium italic">Học tập thông minh - Khẳng định tài năng</p>
        </header>

        <main className="animate-slide-in">
          {renderContent()}
        </main>
      </div>

      <footer className="mt-12 text-slate-400 text-sm text-center">
        &copy; {new Date().getFullYear()} HỌC THÔNG MINH - Nền tảng học tập AI.
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { QuizSetup, Difficulty, LeaderboardEntry, GradeLevel, BookSeries, ContentType, UserProfile, FileData } from '../types';
import Leaderboard from './Leaderboard';

interface SetupViewProps {
  onStart: (setup: QuizSetup) => void;
  error: string | null;
  leaderboard: LeaderboardEntry[];
  initialSetup?: QuizSetup | null;
  userProfile: UserProfile | null;
  onLogout: () => void;
}

const PREDEFINED_TOPICS = [
  { label: 'Lịch sử Việt Nam', icon: '🇻🇳' },
  { label: 'Địa lý thế giới', icon: '🌍' },
  { label: 'Khoa học & Vũ trụ', icon: '🚀' },
  { label: 'Lập trình React', icon: '💻' },
  { label: 'Tiếng Anh giao tiếp', icon: '🇬🇧' },
  { label: 'Văn học Việt Nam', icon: '✍️' },
  { label: 'Toán học vui', icon: '🔢' },
  { label: 'Kỹ năng sống', icon: '💡' },
];

const PREDEFINED_SUBJECTS = [
  'Toán học', 'Ngữ văn', 'Tiếng Anh', 'Vật lý', 'Hóa học', 'Sinh học', 'Lịch sử', 'Địa lý', 'Tin học', 'GDCD'
];

const GRADE_STRUCTURE: Record<GradeLevel, string[]> = {
  primary: ['1', '2', '3', '4', '5'],
  secondary: ['6', '7', '8', '9'],
  highschool: ['10', '11', '12'],
  advanced: ['Đại học', 'Sau đại học', 'Đi làm'],
};

const SetupView: React.FC<SetupViewProps> = ({ onStart, error, leaderboard, initialSetup, userProfile, onLogout }) => {
  // Xử lý tách môn học từ chủ đề cũ nếu có định dạng "Môn: Bài"
  const getInitialTopicParts = () => {
    if (initialSetup?.topic && initialSetup.topic.includes(': ')) {
      const [s, ...t] = initialSetup.topic.split(': ');
      return { subject: s, topic: t.join(': ') };
    }
    return { subject: '', topic: initialSetup?.topic || '' };
  };

  const initialParts = getInitialTopicParts();
  const [subject, setSubject] = useState(initialParts.subject);
  const [topic, setTopic] = useState(initialParts.topic);
  const [contentType, setContentType] = useState<ContentType>(initialSetup?.contentType || 'topic');
  const [count, setCount] = useState(initialSetup?.count || 15);
  const [difficulty, setDifficulty] = useState<Difficulty>(initialSetup?.difficulty || 'medium');
  const [gradeNumber, setGradeNumber] = useState(initialSetup?.gradeNumber || userProfile?.gradeNumber || '1');
  const [bookSeries, setBookSeries] = useState<BookSeries>(initialSetup?.bookSeries || 'none');
  const [advancedInstructions, setAdvancedInstructions] = useState(initialSetup?.advancedInstructions || '');
  const [showAdvanced, setShowAdvanced] = useState(!!initialSetup?.advancedInstructions);
  const [fileData, setFileData] = useState<FileData | undefined>(initialSetup?.fileData);
  const [fileName, setFileName] = useState<string>('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!initialSetup && userProfile) {
      setGradeNumber(GRADE_STRUCTURE[userProfile.gradeLevel][0]);
    }
  }, [userProfile, initialSetup]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFileName(file.name);
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        setFileData({
          data: base64String,
          mimeType: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const removeFile = () => {
    setFileData(undefined);
    setFileName('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleContentTypeChange = (type: ContentType) => {
    setContentType(type);
    if (type === 'topic' && count < 15) {
      setCount(15);
    } else if (type === 'lesson' && count < 10) {
      setCount(10);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userProfile) return;

    if (!topic.trim() && !fileData) return;

    let finalCount = count;
    if (contentType === 'topic' && count < 15) finalCount = 15;
    if (contentType === 'lesson' && count < 10) finalCount = 10;
    if (count > 50) finalCount = 50;

    const finalTopic = subject ? `${subject}: ${topic}` : (topic || 'Dựa trên tài liệu đã tải lên');

    onStart({ 
      playerName: userProfile.playerName, 
      topic: finalTopic, 
      contentType,
      count: finalCount, 
      difficulty, 
      gradeLevel: userProfile.gradeLevel, 
      gradeNumber,
      className: userProfile.className,
      schoolName: userProfile.schoolName,
      province: userProfile.province,
      bookSeries,
      advancedInstructions,
      fileData
    });
  };

  const selectTopic = (selectedTopic: string) => {
    setTopic(selectedTopic);
    setSubject('');
  };

  return (
    <div className="space-y-8 pb-12 animate-slide-in">
      {/* Header Profile */}
      <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-lg flex justify-between items-center">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-xl shadow-inner">
            👤
          </div>
          <div>
            <p className="text-indigo-100 text-[10px] font-bold uppercase tracking-widest">Học viên</p>
            <h3 className="text-xl font-bold leading-none mb-1">{userProfile?.playerName}</h3>
            <p className="text-[11px] opacity-80">{userProfile?.className} • {userProfile?.schoolName}</p>
          </div>
        </div>
        <button 
          onClick={onLogout}
          className="bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl transition-all text-xs font-bold border border-white/10 shadow-sm"
        >
          Đăng xuất
        </button>
      </div>

      <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50">
        <h2 className="text-2xl font-bold text-slate-800 mb-6 flex items-center">
            <span className="mr-3 text-indigo-600">🎯</span>
            Thiết lập nội dung bài học
        </h2>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-sm font-medium">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Section: Upload Tài liệu */}
          <div className="space-y-3">
            <label className="block text-sm font-semibold text-slate-700">Tải ảnh bài học hoặc tài liệu (Tùy chọn)</label>
            <div 
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer ${fileData ? 'border-green-400 bg-green-50' : 'border-slate-200 hover:border-indigo-400 hover:bg-indigo-50/30'}`}
            >
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept="image/*,.pdf,.txt"
              />
              {!fileData ? (
                <div className="space-y-2">
                  <div className="text-3xl">📁</div>
                  <div className="text-sm font-medium text-slate-600">Nhấn để tải lên tài liệu học tập</div>
                  <div className="text-[10px] text-slate-400 uppercase tracking-widest">Hỗ trợ Ảnh, PDF, TXT</div>
                </div>
              ) : (
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="text-2xl">✅</div>
                    <div className="text-left">
                      <div className="text-sm font-bold text-green-700 truncate max-w-[200px]">{fileName || 'Tài liệu đã chọn'}</div>
                      <div className="text-[10px] text-green-600">Tài liệu đã sẵn sàng để AI phân tích</div>
                    </div>
                  </div>
                  <button 
                    type="button" 
                    onClick={(e) => { e.stopPropagation(); removeFile(); }}
                    className="p-2 hover:bg-red-100 rounded-lg text-red-500 transition-colors"
                  >
                    ✕
                  </button>
                </div>
              )}
            </div>
            {fileData && (
              <p className="text-[11px] text-indigo-500 font-medium italic">* AI sẽ tự động tạo câu hỏi dựa trên nội dung tệp này.</p>
            )}
          </div>

          <div className="space-y-4">
            <div className="flex bg-slate-50 p-1 rounded-2xl border-2 border-slate-100">
              <button
                type="button"
                onClick={() => handleContentTypeChange('topic')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'topic' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Chủ đề tổng quát
              </button>
              <button
                type="button"
                onClick={() => handleContentTypeChange('lesson')}
                className={`flex-1 py-3 px-4 rounded-xl text-sm font-bold transition-all ${contentType === 'lesson' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Bài học cụ thể
              </button>
            </div>

            {contentType === 'lesson' && (
              <div className="animate-slide-in">
                <label className="block text-sm font-semibold text-slate-700 mb-2">Chọn Môn học</label>
                <div className="flex flex-wrap gap-2 mb-4">
                  {PREDEFINED_SUBJECTS.map(s => (
                    <button
                      key={s}
                      type="button"
                      onClick={() => setSubject(s)}
                      className={`px-4 py-2 rounded-xl text-xs font-bold transition-all border-2 ${
                        subject === s 
                        ? 'bg-indigo-100 text-indigo-700 border-indigo-300' 
                        : 'bg-white text-slate-500 border-slate-100 hover:border-indigo-200'
                      }`}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">
                {contentType === 'topic' ? 'Tên Chủ đề' : 'Tên Bài học'}
              </label>
              <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
                    {contentType === 'topic' ? '🌍' : '📖'}
                  </span>
                  <input
                      type="text"
                      placeholder={contentType === 'topic' ? "Ví dụ: Lịch sử nhà Trần, Hải dương học..." : "Ví dụ: Bài 5 - Các nước Đông Nam Á..."}
                      className="w-full pl-11 pr-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800"
                      value={topic}
                      onChange={(e) => setTopic(e.target.value)}
                      required={!fileData}
                  />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Khối lớp học</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={gradeNumber}
                  onChange={(e) => setGradeNumber(e.target.value)}
                >
                  {userProfile && GRADE_STRUCTURE[userProfile.gradeLevel].map(c => (
                    <option key={c} value={c}>{userProfile.gradeLevel === 'advanced' ? c : `Khối ${c}`}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Số câu hỏi</label>
                <div className="relative">
                  <input
                      type="number"
                      min={contentType === 'topic' ? 15 : 10}
                      max={50}
                      className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 font-bold"
                      value={count}
                      onChange={(e) => setCount(parseInt(e.target.value) || 0)}
                  />
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 text-xs text-slate-400 font-bold">CÂU</span>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Bộ sách giáo khoa</label>
                <select
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 appearance-none transition-all"
                  value={bookSeries}
                  onChange={(e) => setBookSeries(e.target.value as BookSeries)}
                >
                  <option value="none">Mặc định / Khác</option>
                  <option value="canh_dieu">Cánh diều</option>
                  <option value="ket_noi_tri_thuc">Kết nối tri thức</option>
                  <option value="chan_troi_sang_tao">Chân trời sáng tạo</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Độ khó</label>
                <div className="grid grid-cols-3 gap-2">
                  {(['easy', 'medium', 'hard'] as Difficulty[]).map((d) => (
                    <button
                      key={d}
                      type="button"
                      onClick={() => setDifficulty(d)}
                      className={`py-3 rounded-2xl text-[10px] font-bold transition-all border-2 ${
                        difficulty === d 
                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
                        : 'bg-white text-slate-500 border-slate-100 hover:border-indigo-200'
                      }`}
                    >
                      {d === 'easy' ? 'DỄ' : d === 'medium' ? 'VỪA' : 'KHÓ'}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {contentType === 'topic' && (
            <div>
              <span className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3 block">Gợi ý nhanh chủ đề:</span>
              <div className="flex flex-wrap gap-2">
                {PREDEFINED_TOPICS.map((t) => (
                  <button
                    key={t.label}
                    type="button"
                    onClick={() => selectTopic(t.label)}
                    className={`px-3 py-1.5 rounded-full text-xs font-medium transition-all border ${
                      topic === t.label 
                        ? 'bg-indigo-600 text-white border-indigo-600' 
                        : 'bg-white text-slate-600 border-slate-200 hover:border-indigo-300'
                    }`}
                  >
                    <span className="mr-1">{t.icon}</span> {t.label}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div>
            <button 
                type="button" 
                onClick={() => setShowAdvanced(!showAdvanced)}
                className="text-indigo-600 text-sm font-semibold flex items-center hover:text-indigo-700 transition-colors"
            >
                {showAdvanced ? '− Thu gọn yêu cầu nâng cao' : '+ Thêm yêu cầu nâng cao (tùy chọn)'}
            </button>

            {showAdvanced && (
                <div className="mt-4 animate-slide-in">
                    <textarea
                        placeholder="Ví dụ: Tập trung vào các mốc thời gian, bỏ qua các câu hỏi lý thuyết suông..."
                        className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none text-slate-800 min-h-[100px]"
                        value={advancedInstructions}
                        onChange={(e) => setAdvancedInstructions(e.target.value)}
                    />
                </div>
            )}
          </div>

          <button
            type="submit"
            disabled={!topic.trim() && !fileData}
            className="w-full bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-300 text-white font-bold py-5 rounded-2xl transition-all shadow-lg shadow-indigo-200 mt-4 active:scale-95 flex items-center justify-center gap-2"
          >
            {initialSetup ? 'Cập nhật & Bắt đầu lại' : (
              <>
                <span>🚀</span> Bắt đầu bài trắc nghiệm ngay
              </>
            )}
          </button>
        </form>
      </div>

      {leaderboard.length > 0 && (
          <div className="bg-white rounded-3xl shadow-xl shadow-slate-100 p-8 border border-slate-100">
              <h2 className="text-xl font-bold text-slate-800 mb-6 flex items-center">
                <span className="mr-3 text-yellow-500">🏆</span>
                Bảng xếp hạng vinh danh
              </h2>
              <Leaderboard entries={leaderboard} />
          </div>
      )}
    </div>
  );
};

export default SetupView;

export interface Question {
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export type Difficulty = 'easy' | 'medium' | 'hard';
export type GradeLevel = 'primary' | 'secondary' | 'highschool' | 'advanced';
export type BookSeries = 'canh_dieu' | 'ket_noi_tri_thuc' | 'chan_troi_sang_tao' | 'none';
export type ContentType = 'topic' | 'lesson';

export interface FileData {
  data: string; // base64 string
  mimeType: string;
}

export interface UserProfile {
  id: string;
  loginId: string; // Gmail hoặc Số điện thoại
  playerName: string;
  schoolName: string;
  className: string;
  province: string;
  gradeLevel: GradeLevel;
  gradeNumber: string;
  createdAt: number; // Thời điểm đăng ký (timestamp)
}

export interface QuizSetup {
  playerName: string;
  topic: string;
  contentType: ContentType;
  count: number;
  difficulty: Difficulty;
  gradeLevel: GradeLevel;
  gradeNumber: string;
  className: string;
  schoolName: string;
  province: string;
  bookSeries: BookSeries;
  advancedInstructions?: string;
  fileData?: FileData;
}

export enum AppState {
  AUTH,
  SETUP,
  LOADING,
  PLAYING,
  RESULTS
}

export interface UserAnswer {
  questionIndex: number;
  selectedIndex: number;
  isCorrect: boolean;
}

export interface LeaderboardEntry {
  id: string;
  playerName: string;
  schoolName?: string;
  className?: string;
  province?: string;
  score: number;
  total: number;
  topic: string;
  date: number;
}

import React, { useState, useEffect } from 'react';
import { UserProfile, GradeLevel } from '../types';

interface AuthViewProps {
  onLogin: (user: UserProfile) => void;
}

const USERS_KEY = 'brainboost_users_v1';
const TRIAL_DAYS = 7;
const DEFAULT_PASSWORD = 'a12345';

const AuthView: React.FC<AuthViewProps> = ({ onLogin }) => {
  const [isRegistering, setIsRegistering] = useState(false);
  const [loginId, setLoginId] = useState(''); // Gmail hoặc SĐT
  const [password, setPassword] = useState(''); // Mật khẩu kích hoạt
  const [playerName, setPlayerName] = useState('');
  const [schoolName, setSchoolName] = useState('');
  const [className, setClassName] = useState('');
  const [province, setProvince] = useState('');
  const [gradeLevel, setGradeLevel] = useState<GradeLevel>('primary');
  const [error, setError] = useState('');
  const [isExpired, setIsExpired] = useState(false);
  const [daysLeft, setDaysLeft] = useState<number | null>(null);

  const getUsers = (): UserProfile[] => {
    const saved = localStorage.getItem(USERS_KEY);
    return saved ? JSON.parse(saved) : [];
  };

  // Kiểm tra trạng thái dùng thử khi nhập loginId
  useEffect(() => {
    if (!isRegistering && loginId.trim()) {
      const users = getUsers();
      const user = users.find(u => u.loginId === loginId);
      if (user) {
        const now = Date.now();
        const diffTime = now - user.createdAt;
        const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
        const remaining = TRIAL_DAYS - diffDays;

        setDaysLeft(remaining > 0 ? remaining : 0);
        setIsExpired(diffDays >= TRIAL_DAYS);
      } else {
        setIsExpired(false);
        setDaysLeft(null);
      }
    } else {
      setIsExpired(false);
      setDaysLeft(null);
    }
  }, [loginId, isRegistering]);

  const handleAuth = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const users = getUsers();

    if (isRegistering) {
      if (users.some(u => u.loginId === loginId)) {
        setError('Tài khoản này đã tồn tại!');
        return;
      }
      const newUser: UserProfile = {
        id: Math.random().toString(36).substr(2, 9),
        loginId,
        playerName,
        schoolName,
        className,
        province,
        gradeLevel,
        gradeNumber: '1',
        createdAt: Date.now()
      };
      localStorage.setItem(USERS_KEY, JSON.stringify([...users, newUser]));
      onLogin(newUser);
    } else {
      const user = users.find(u => u.loginId === loginId);
      if (user) {
        // Nếu hết hạn dùng thử, yêu cầu mật khẩu
        if (isExpired) {
          if (password !== DEFAULT_PASSWORD) {
            setError('Mật khẩu kích hoạt không chính xác. Vui lòng liên hệ quản trị viên!');
            return;
          }
        }
        onLogin(user);
      } else {
        setError('Không tìm thấy tài khoản. Vui lòng đăng ký!');
      }
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl shadow-indigo-100 p-8 border border-indigo-50 animate-slide-in">
      <div className="text-center mb-8">
        <h2 className="text-2xl font-bold text-slate-800">
          {isRegistering ? 'Đăng ký thông tin' : 'Chào mừng trở lại'}
        </h2>
        <p className="text-slate-500 text-sm mt-1">
          {isRegistering ? 'Nhập thông tin một lần để bắt đầu học tập' : 'Đăng nhập để tiếp tục quá trình học'}
        </p>

        {!isRegistering && daysLeft !== null && (
          <div className={`mt-3 inline-block px-4 py-1.5 rounded-full text-xs font-bold ${isExpired ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}`}>
            {isExpired ? '⚠️ Đã hết hạn dùng thử 7 ngày' : `🕒 Còn lại ${daysLeft} ngày dùng thử miễn phí`}
          </div>
        )}
      </div>

      <form onSubmit={handleAuth} className="space-y-4">
        {error && (
          <div className="p-4 bg-red-50 text-red-600 rounded-2xl text-sm font-medium border border-red-100">
            {error}
          </div>
        )}

        <div>
          <label className="block text-sm font-semibold text-slate-700 mb-2">Gmail hoặc Số điện thoại</label>
          <input
            type="text"
            required
            className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none transition-all"
            placeholder="example@gmail.com hoặc 09xxx..."
            value={loginId}
            onChange={(e) => setLoginId(e.target.value)}
          />
        </div>

        {isExpired && !isRegistering && (
          <div className="animate-slide-in">
            <label className="block text-sm font-semibold text-red-600 mb-2 font-bold italic flex items-center gap-2">
               🔒 Nhập mật khẩu kích hoạt để tiếp tục
            </label>
            <input
              type="password"
              required
              className="w-full px-5 py-4 bg-red-50 border-2 border-red-200 rounded-2xl focus:border-red-500 outline-none transition-all"
              placeholder="Nhập mật khẩu (Mặc định: a12345)"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <p className="text-[10px] text-slate-400 mt-2 px-1 italic">Ứng dụng đã hết thời hạn dùng thử 7 ngày. Vui lòng nhập mật khẩu được cấp.</p>
          </div>
        )}

        {isRegistering && (
          <div className="space-y-4 animate-slide-in">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Họ và tên</label>
                <input
                  type="text"
                  required
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none transition-all"
                  placeholder="Nguyễn Văn A"
                  value={playerName}
                  onChange={(e) => setPlayerName(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Lớp</label>
                <input
                  type="text"
                  required
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none transition-all"
                  placeholder="12A1"
                  value={className}
                  onChange={(e) => setClassName(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Trường học</label>
              <input
                type="text"
                required
                className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none transition-all"
                placeholder="THPT Chuyên..."
                value={schoolName}
                onChange={(e) => setSchoolName(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Tỉnh/Thành phố</label>
              <input
                type="text"
                required
                className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none transition-all"
                placeholder="Hà Nội"
                value={province}
                onChange={(e) => setProvince(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 mb-2">Cấp học</label>
              <select
                className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 outline-none transition-all"
                value={gradeLevel}
                onChange={(e) => setGradeLevel(e.target.value as GradeLevel)}
              >
                <option value="primary">Tiểu học</option>
                <option value="secondary">THCS</option>
                <option value="highschool">THPT</option>
                <option value="advanced">Đại học / Đi làm</option>
              </select>
            </div>
          </div>
        )}

        <button
          type="submit"
          className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl transition-all shadow-lg shadow-indigo-100 mt-4 active:scale-95"
        >
          {isRegistering ? 'Hoàn tất đăng ký & Dùng thử 7 ngày' : (isExpired ? 'Kích hoạt & Đăng nhập' : 'Đăng nhập ngay')}
        </button>

        <div className="text-center mt-6">
          <button
            type="button"
            onClick={() => {
              setIsRegistering(!isRegistering);
              setError('');
              setPassword('');
            }}
            className="text-indigo-600 font-semibold hover:underline text-sm"
          >
            {isRegistering ? 'Đã có tài khoản? Đăng nhập' : 'Chưa có tài khoản? Đăng ký tại đây'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default AuthView;

import React, { useState, useEffect } from 'react';
import { AppState, Question, QuizSetup, UserAnswer, LeaderboardEntry, UserProfile } from './types';
import { generateQuiz } from './services/geminiService';
import SetupView from './components/SetupView';
import QuizEngine from './components/QuizEngine';
import ResultsView from './components/ResultsView';
import LoadingView from './components/LoadingView';
import AuthView from './components/AuthView';

const LEADERBOARD_KEY = 'brainboost_leaderboard_v2';
const USERS_KEY = 'brainboost_users_v1';
const CURRENT_USER_KEY = 'brainboost_current_user';
const LAST_SETUP_KEY = 'brainboost_last_setup';
const TRIAL_DAYS = 7;

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(AppState.AUTH);
  const [isInitializing, setIsInitializing] = useState(true);
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(null);
  const [questions, setQuestions] = useState<Question[]>([]);
  const [userAnswers, setUserAnswers] = useState<UserAnswer[]>([]);
  const [currentSetup, setCurrentSetup] = useState<QuizSetup | null>(null);
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    // 1. Tải bảng xếp hạng
    const savedLeaderboard = localStorage.getItem(LEADERBOARD_KEY);
    if (savedLeaderboard) {
      try { setLeaderboard(JSON.parse(savedLeaderboard)); } catch (e) {}
    }

    // 2. Kiểm tra phiên đăng nhập cũ
    const savedUser = localStorage.getItem(CURRENT_USER_KEY);
    if (savedUser) {
      try {
        const user: UserProfile = JSON.parse(savedUser);

        // Kiểm tra xem có bị hết hạn dùng thử không khi tự động đăng nhập
        const diffTime = Date.now() - (user.createdAt || 0);
        const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays >= TRIAL_DAYS) {
          // Nếu đã hết hạn, yêu cầu đăng nhập lại để xác thực mật khẩu
          setCurrentUser(null);
          localStorage.removeItem(CURRENT_USER_KEY);
          setState(AppState.AUTH);
        } else {
          setCurrentUser(user);
          // Tải thiết lập học tập gần nhất
          const savedSetup = localStorage.getItem(LAST_SETUP_KEY);
          if (savedSetup) {
            setCurrentSetup(JSON.parse(savedSetup));
          }
          setState(AppState.SETUP);
        }
      } catch (e) {
        localStorage.removeItem(CURRENT_USER_KEY);
      }
    }

    setIsInitializing(false);
  }, []);

  const handleLogin = (user: UserProfile) => {
    setCurrentUser(user);
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(user));
    setState(AppState.SETUP);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentSetup(null);
    localStorage.removeItem(CURRENT_USER_KEY);
    localStorage.removeItem(LAST_SETUP_KEY);
    setState(AppState.AUTH);
  };

  const saveScore = (setup: QuizSetup, score: number, total: number) => {
    const newEntry: LeaderboardEntry = {
      id: Math.random().toString(36).substr(2, 9),
      playerName: setup.playerName,
      schoolName: setup.schoolName,
      className: setup.className,
      province: setup.province,
      score,
      total,
      topic: setup.topic,
      date: Date.now()
    };
    const updated = [newEntry, ...leaderboard]
      .sort((a, b) => (b.score / b.total) - (a.score / a.total) || b.date - a.date)
      .slice(0, 15);

    setLeaderboard(updated);
    localStorage.setItem(LEADERBOARD_KEY, JSON.stringify(updated));
  };

  const startQuiz = async (setup: QuizSetup) => {
    setState(AppState.LOADING);
    setError(null);
    setCurrentSetup(setup);

    localStorage.setItem(LAST_SETUP_KEY, JSON.stringify(setup));

    try {
      const generatedQuestions = await generateQuiz(setup);
      if (generatedQuestions.length === 0) {
        throw new Error("Không có câu hỏi nào được tạo ra.");
      }
      setQuestions(generatedQuestions);
      setUserAnswers([]);
      setState(AppState.PLAYING);
    } catch (err: any) {
      setError(err.message || "Đã xảy ra lỗi không mong muốn");
      setState(AppState.SETUP);
    }
  };

  const handleComplete = (answers: UserAnswer[]) => {
    setUserAnswers(answers);
    const score = answers.filter(a => a.isCorrect).length;
    if (currentSetup) {
      saveScore(currentSetup, score, questions.length);
    }
    setState(AppState.RESULTS);
  };

  const reset = () => {
    setState(AppState.SETUP);
    setQuestions([]);
    setUserAnswers([]);
    setError(null);
  };

  if (isInitializing) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="animate-pulse flex flex-col items-center">
          <div className="w-12 h-12 bg-indigo-600 rounded-2xl mb-4"></div>
          <p className="text-slate-400 font-medium">Đang khởi động...</p>
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch (state) {
      case AppState.AUTH:
        return <AuthView onLogin={handleLogin} />;
      case AppState.SETUP:
        return (
          <SetupView 
            onStart={startQuiz} 
            error={error} 
            leaderboard={leaderboard} 
            initialSetup={currentSetup}
            userProfile={currentUser}
            onLogout={handleLogout}
          />
        );
      case AppState.LOADING:
        return <LoadingView onCancel={reset} />;
      case AppState.PLAYING:
        return (
          <QuizEngine 
            questions={questions} 
            onComplete={handleComplete} 
            onQuit={reset}
          />
        );
      case AppState.RESULTS:
        return (
          <ResultsView 
            questions={questions} 
            answers={userAnswers} 
            onRestart={reset}
            setup={currentSetup}
            leaderboard={leaderboard}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-start py-8 px-4 sm:px-6 lg:px-8">
      <div className="w-full max-w-2xl">
        <header className="text-center mb-8">
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight mb-2">
            HỌC <span className="text-indigo-600">THÔNG MINH</span>
          </h1>
          <p className="text-slate-500 font-medium italic">Học tập thông minh - Khẳng định tài năng</p>
        </header>

        <main className="animate-slide-in">
          {renderContent()}
        </main>
      </div>

      <footer className="mt-12 text-slate-400 text-sm text-center">
        &copy; {new Date().getFullYear()} HỌC THÔNG MINH - Nền tảng học tập AI.
      </footer>
    </div>
  );
};

export default App;
